// The five places in the client rail (and the phone bottom bar). A place
// is either one page or a row of tabs; a tabbed place opens its last-used
// visible tab (CLIENT_lastTab) and shows the row in the top bar.
const CLIENT_PLACES = [
  { key: "home", label: "Home", page: "dashboard", icon: <HomeIcon /> },
  {
    key: "messages",
    label: "Messages",
    page: "messages",
    icon: <ChatIcon width="16" height="16" strokeWidth="1.8" />,
  },
  {
    key: "finances",
    label: "Finances",
    tabs: ["budget", "bank", "receivables", "giving", "payroll"],
    icon: <BankIcon />,
  },
  { key: "reports", label: "Reports", page: "reports", icon: <DownloadIcon /> },
  { key: "documents", label: "Documents", page: "documents", icon: <FolderIcon /> },
];
const CLIENT_PLACE_OF_PAGE = {
  dashboard: "home",
  messages: "messages",
  budget: "finances",
  bank: "finances",
  receivables: "finances",
  giving: "finances",
  payroll: "finances",
  reports: "reports",
  documents: "documents",
  "client-settings": "settings",
  milestone: "settings",
};
function CLIENT_placeOf(page) {
  const key = CLIENT_PLACE_OF_PAGE[page];
  return key ? CLIENT_PLACES.find((p) => p.key === key) || null : null;
}
// Last tab opened inside a tabbed place, this browser session only.
function CLIENT_lastTab(placeKey, pages) {
  let last = null;
  try {
    last = window.sessionStorage.getItem("mgb_client_tab_" + placeKey);
  } catch (e) {}
  return last && pages.indexOf(last) !== -1 ? last : pages[0];
}
// Fourth hash segment on a client page (#/client/<id>/reports/packet).
// Tagged with its client: a sub is view state for that one client and
// never carries over to the next client's tab.
function CLIENT_subFromHash() {
  try {
    const parts = String(window.location.hash || "").replace(/^#\/?/, "").split(/[?]/)[0].split("/").filter(Boolean);
    // Tasks p2 S6: #/client/<id>/needs[/<request id>] is Messages › Requests
    // ("What we need from you", ClientNeeds.jsx), focused on that request.
    if (parts[0] === "client" && parts[1] && parts[2] === "needs")
      return {
        clientId: decodeURIComponent(parts[1]),
        page: "messages",
        sub: "requests",
        focus: /^[0-9a-f-]{36}$/.test(parts[3] || "") ? parts[3] : null,
      };
    if (parts[0] === "client" && parts[2] && parts[3])
      return { clientId: decodeURIComponent(parts[1]), page: parts[2], sub: parts[3] };
  } catch (e) {}
  return { clientId: null, page: null, sub: null };
}
// One card for anything Basic doesn't include (owner-approved: replaces
// the inline upsell panels). See plans opens Settings › Plan; with
// onTakeTour, "Take the Pro tour" opens it and starts the Pro tour
// (components/tour/Tour.jsx).
function CLIENT_LockedCard({ title, text, onSeePlans, onTakeTour }) {
  const tour = onTakeTour && typeof TOUR_start === "function";
  return (
    <div className="card client-locked-card">
      <h3 className="card-title" style={{ marginBottom: 4 }}>
        {title}
      </h3>
      <p className="card-subtitle" style={{ margin: "0 0 14px" }}>
        {text}
      </p>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
        <button type="button" className="btn-primary" onClick={onSeePlans}>
          See plans
        </button>
        {tour && (
          <button type="button" className="btn-secondary" onClick={onTakeTour}>
            Take the Pro tour
          </button>
        )}
      </div>
    </div>
  );
}
// Home (client view): "Needs you" list beside the organization card. The
// dashboard's own KPI cards below are the tiles. `needs` items:
// { key, text, sub?, action, onClick, tone? } — built in App from data it
// already loads (unread messages, document requests, budget approval).
function CLIENT_HomeTop({ client, access, needs: baseNeeds, onOpenMilestone, onSeePlans, realClient }) {
  const { byId } = useMilestones(client ? [client.id] : []);
  // Client org profile (hidden, OP_store.js): "Finish your organization
  // profile" while the gate is on and the profile is incomplete; else nothing.
  const opNeed = typeof OP_useNeedsItem === "function" ? OP_useNeedsItem(!!realClient) : null;
  const needs = opNeed ? baseNeeds.concat([opNeed]) : baseNeeds;
  const ms = client ? byId[client.id] : null;
  const cur = ms && ms.current;
  const msText = cur && !ms.unconfirmed ? (cur.churchPlant ? cur.name : cur.roman + " · " + cur.name) : null;
  const showOrg = !(access && access.isCategoryScoped);
  return (
    <div className={"client-home-top" + (showOrg ? "" : " no-org")}>
      <div className="card client-needs" data-tour="client-needs">
        <h3 className="card-title" style={{ marginBottom: 8 }}>
          Needs you
        </h3>
        {needs.length === 0 ? (
          <p className="card-subtitle" style={{ margin: 0 }}>
            You're all caught up. Nothing is waiting on you.
          </p>
        ) : (
          <ul className="client-needs-list">
            {needs.map((n) => (
              <li key={n.key} className={"client-needs-item" + (n.tone ? " " + n.tone : "")}>
                <div className="client-needs-main">
                  <strong>{n.text}</strong>
                  {n.sub ? <span className="client-needs-sub">{n.sub}</span> : null}
                </div>
                <button type="button" className="btn-secondary btn-sm" onClick={n.onClick}>
                  {n.action}
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>
      {showOrg && (
        <div className="card client-org-card">
          <div className="client-org-name">{client.name || "Your organization"}</div>
          <button
            type="button"
            className="client-org-ms"
            data-tour="milestone"
            onClick={onOpenMilestone}
            title="Open your milestone"
          >
            <span className="client-org-label">Milestone</span>
            <span>{msText || "Not set yet"}</span>
          </button>
          <div className="client-org-plan">
            <span className="client-org-label">Plan</span>
            <span>{planLabel(access.plan)}</span>
          </div>
          <button type="button" className="btn-secondary btn-sm" onClick={onSeePlans}>
            See plans
          </button>
        </div>
      )}
    </div>
  );
}
// Phone bottom bar (client view, CSS shows it under 760px): Home,
// Messages, Finances, Reports, and More → Documents, Settings.
function CLIENT_TabBar({ page, visibleKeys, badges, onSelect, onOpenSettings }) {
  const [moreOpen, setMoreOpen] = useState(false);
  const placeOf = CLIENT_PLACE_OF_PAGE[page];
  const pagesOf = (place) =>
    place.tabs ? place.tabs.filter((k) => visibleKeys.has(k)) : visibleKeys.has(place.page) ? [place.page] : [];
  const main = CLIENT_PLACES.filter((p) => p.key !== "documents" && pagesOf(p).length);
  const docs = CLIENT_PLACES.find((p) => p.key === "documents");
  const showDocs = pagesOf(docs).length > 0;
  const moreActive = placeOf === "documents" || placeOf === "settings";
  return (
    <nav className="client-tabbar" aria-label="Main">
      {main.map((place) => {
        const pages = pagesOf(place);
        const active = placeOf === place.key;
        return (
          <button
            key={place.key}
            type="button"
            className={"client-tabbar-item" + (active ? " active" : "")}
            aria-current={active ? "page" : undefined}
            onClick={() => {
              setMoreOpen(false);
              onSelect(place.tabs ? CLIENT_lastTab(place.key, pages) : place.page);
            }}
          >
            {place.icon}
            <span>{place.label}</span>
            {pages.some((k) => badges[k]) && <span className="client-tabbar-dot" aria-label="Unread" />}
          </button>
        );
      })}
      <button
        type="button"
        className={"client-tabbar-item" + (moreActive ? " active" : "")}
        aria-expanded={moreOpen}
        onClick={() => setMoreOpen((o) => !o)}
      >
        <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
          <circle cx="5" cy="12" r="2" />
          <circle cx="12" cy="12" r="2" />
          <circle cx="19" cy="12" r="2" />
        </svg>
        <span>More</span>
        {showDocs && badges.documents && <span className="client-tabbar-dot" aria-label="Unread" />}
      </button>
      {moreOpen && (
        <div className="client-tabbar-more" role="menu">
          {showDocs && (
            <button type="button" role="menuitem" onClick={() => { setMoreOpen(false); onSelect("documents"); }}>
              {docs.icon}
              <span>Documents</span>
            </button>
          )}
          <button type="button" role="menuitem" onClick={() => { setMoreOpen(false); onOpenSettings(); }}>
            <ST_GearIcon width="18" height="18" />
            <span>Settings</span>
          </button>
        </div>
      )}
    </nav>
  );
}
// The "?" menu in the client top bar, beside the bell (owner request
// 2026-10-09: "add the ? menu for clients"): the client's version of the
// staff bar's TB_HelpButton (components/staff/TopBar.jsx), for client users
// and staff previewing as one. Items, only those that apply: the client
// tour; the Pro tour while the plan shown is below Pro (as Settings › Help);
// Messages and What we need from you (Messages › Requests), with the
// messages tab; Settings › Help; Contact support (the
// footer's mailto). Staff previewing get "Preview the tour" labels, as in
// Settings › Help. Borrows TopBar.jsx's TB_useMenu (Esc closes and refocuses
// the button, arrow keys move, the first item takes focus) and
// TB_QuestionIcon, and the .tb-panel / .tb-menu-item look; App renders it
// only when TB_useMenu exists. Styles: styles.css .client-help. Tour hook:
// data-tour="client-help" (Tour.jsx, the client tour's last step).
const CLIENT_SUPPORT_MAILTO = "mailto:admin@mygoodbooks.org?subject=MyGoodBooks%20Support";
function CLIENT_HelpButton({ plan, preview, canMessage, onOpenMessages, onOpenNeeds, onOpenHelp, realClient }) {
  const menu = TB_useMenu();
  // Client org profile (hidden, OP_store.js): null unless the gate is on.
  const opItem = typeof OP_useHelpItem === "function" ? OP_useHelpItem(!preview && !!realClient) : null;
  const hasTour = typeof TOUR_start === "function";
  const belowPro = planShownKey(plan || "basic") !== "premium";
  const items = [];
  if (hasTour) items.push({ key: "tour", label: preview ? "Preview the tour" : "Take the tour", run: () => TOUR_start() });
  if (hasTour && belowPro)
    items.push({ key: "pro-tour", label: preview ? "Preview the Pro tour" : "Take the Pro tour", run: () => TOUR_start("pro") });
  if (canMessage) items.push({ key: "messages", label: "Message your bookkeeper", run: onOpenMessages });
  // Tasks p2 S6: Messages › Requests (ClientNeeds.jsx), where they answer.
  if (canMessage && onOpenNeeds) items.push({ key: "needs", label: "What we need from you", run: onOpenNeeds });
  if (opItem) items.push(opItem);
  items.push({ key: "help", label: "Help and settings", run: onOpenHelp });
  items.push({
    key: "support",
    label: "Contact support",
    run: () => {
      window.location.href = CLIENT_SUPPORT_MAILTO;
    },
  });
  // Usage stats ("client-help", USAGE_ACTION_LABELS): real client users
  // only, like the tours; staff previewing aren't counted.
  const track = (key) => {
    if (!preview && window.MGB_track) window.MGB_track("client-help", key);
  };
  return (
    <div className="client-help" ref={menu.rootRef} onKeyDown={menu.onMenuKeyDown} data-tour="client-help">
      <button
        ref={menu.triggerRef}
        type="button"
        className="tb-icon-btn"
        aria-label="Help"
        title="Help"
        aria-haspopup="true"
        aria-expanded={menu.open}
        onClick={() => menu.setOpen(!menu.open)}
      >
        <TB_QuestionIcon />
      </button>
      {menu.open && (
        <div className="tb-panel tb-menu" role="menu" aria-label="Help">
          {items.map((it, n) => (
            <button
              key={it.key}
              type="button"
              role="menuitem"
              className="tb-menu-item"
              autoFocus={n === 0}
              onClick={() => {
                menu.close(false);
                track(it.key);
                it.run();
              }}
            >
              {it.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
// Messages › Requests: what the bookkeeper is waiting on (document
// requests). Uploading happens on Documents.
function CLIENT_RequestsPanel({ requests, canUpload, onOpenDocuments }) {
  const today = todayLocal();
  const open = (requests || []).filter((r) => r.status === "open" || r.status === "uploaded");
  return (
    <div className="card client-requests">
      <h3 className="card-title" style={{ marginBottom: 4 }}>
        Requests from your bookkeeper
      </h3>
      <p className="card-subtitle" style={{ margin: "0 0 12px" }}>
        {open.length
          ? "Documents your bookkeeper has asked for. Upload them on Documents."
          : "Nothing is waiting on you right now."}
      </p>
      {open.length > 0 && (
        <ul className="client-requests-list">
          {open.map((r) => {
            const overdue = r.status === "open" && r.due_date && r.due_date < today;
            return (
              <li key={r.id} className={"client-requests-item" + (overdue ? " overdue" : "")}>
                <div className="client-requests-main">
                  <strong>{r.title}</strong>
                  {r.details ? <span className="client-requests-details">{r.details}</span> : null}
                </div>
                <span className="client-requests-meta">
                  {r.status === "uploaded"
                    ? "Uploaded, waiting for review"
                    : r.due_date
                      ? (overdue ? "Overdue · due " : "Due ") + fmtDate(r.due_date)
                      : "No due date"}
                </span>
              </li>
            );
          })}
        </ul>
      )}
      {open.length > 0 && canUpload && (
        <button type="button" className="btn-primary" style={{ marginTop: 12 }} onClick={onOpenDocuments}>
          Go to Documents
        </button>
      )}
    </div>
  );
}
function CLIENT_rememberTab(page) {
  const key = CLIENT_PLACE_OF_PAGE[page];
  const place = key && CLIENT_PLACES.find((p) => p.key === key);
  if (!place || !place.tabs) return;
  try {
    window.sessionStorage.setItem("mgb_client_tab_" + key, page);
  } catch (e) {}
}

