function EnterpriseUpgradePage({ client, clientPortalUser }) {
  const showToast = useToast();
  const supabase = window.mgbSupabase;
  // Which tool's row is expanded in the comparison list below — starts with
  // none open so the page loads short, not a wall of text.
  const [openKey, setOpenKey] = useState(null);
  const [requesting, setRequesting] = useState(null);
  // planShownKey: a client still stored on the retired Plus plan reads as
  // Basic here, so it is offered Pro and never sees Plus.
  const current = planShownKey(effectivePlan(client, !clientPortalUser));
  const currentRank = PLAN_ORDER.indexOf(current);
  const loginCount = Math.max(1, (client.users || []).length);

  async function requestUpgrade(plan) {
    const requestedBy =
      (clientPortalUser && (clientPortalUser.name || clientPortalUser.email)) ||
      "Someone at " + client.name;
    if (!supabase) {
      showToast(`Thanks! Your bookkeeper will follow up about ${planLabel(plan)}.`);
      return;
    }
    setRequesting(plan);
    let { error } = await supabase.rpc("request_enterprise_upgrade", {
      p_client_id: client.id,
      p_requested_by: requestedBy,
      p_plan: plan,
    });
    // Until plans-basic-plus-pro.sql runs, the function has no p_plan.
    if (error && error.code === "PGRST202") {
      ({ error } = await supabase.rpc("request_enterprise_upgrade", {
        p_client_id: client.id,
        p_requested_by: `${requestedBy} (wants ${planLabel(plan)})`,
      }));
    }
    setRequesting(null);
    // Never confirm a write that didn't happen.
    if (error) {
      console.warn("Couldn't file upgrade request:", error.message);
      showToast(
        "Couldn't send that request — please email your bookkeeper and we'll sort it out.",
      );
      return;
    }
    showToast(`Thanks! Your bookkeeper will follow up about ${planLabel(plan)}.`);
  }

  return (
    <div className="enterprise-page">
      <MockBanner text="Upgrading isn't automatic yet — your request goes to your bookkeeper, who switches your plan." />

      <div
        className="card"
        style={{ marginBottom: 20, textAlign: "center", padding: "36px 28px" }}
      >
        <div className="eyebrow-badge">Plans</div>
        <h2
          style={{
            fontFamily: "var(--font-heading)",
            fontSize: 26,
            margin: "10px 0 8px",
            color: "var(--ink-strong)",
          }}
        >
          {client.name || "Your organization"} is on {planLabel(current)}
        </h2>
        <p
          style={{
            color: "var(--text-muted)",
            maxWidth: 560,
            margin: "0 auto",
          }}
        >
          Your bookkeeping fee is set by your milestone. Your plan adds the
          portal on top of it, billed monthly. Change plans any time.
        </p>
        {/* Below Pro: the Pro tour of this page (components/tour/Tour.jsx). */}
        {current !== "premium" && typeof TOUR_start === "function" && (
          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              alignItems: "center",
              justifyContent: "center",
              gap: 10,
              marginTop: 18,
            }}
          >
            <button
              type="button"
              className="btn-secondary"
              data-tour="pro-tour-start"
              onClick={() => TOUR_start("pro")}
            >
              Take the Pro tour
            </button>
            <span style={{ color: "var(--text-muted)", fontSize: 13 }}>About 2 minutes</span>
          </div>
        )}
      </div>

      <div className="pricing-grid plans-grid" data-tour="plan-cards" style={{ marginBottom: 20 }}>
        {PLAN_ORDER.map((plan, rank) => {
          const isCurrent = plan === current;
          const recommended = !isCurrent && rank === currentRank + 1;
          return (
            <div
              key={plan}
              data-tour={"plan-card-" + plan}
              className={
                "card pricing-card plan-card" +
                (plan === "premium" ? " pricing-card-premium" : "") +
                (isCurrent ? " plan-card-current" : "") +
                (recommended ? " plan-card-recommended" : "")
              }
            >
              <div className="plan-card-tag">
                {isCurrent ? (
                  <span className="eyebrow-badge">Your plan</span>
                ) : recommended ? (
                  <span className="nav-pro-pill">Recommended</span>
                ) : null}
              </div>
              <h3 className="card-title" style={{ marginTop: 10, marginBottom: 2 }}>
                {planLabel(plan)}
              </h3>
              <div
                className={
                  "pricing-value" + (plan === "premium" ? " pricing-value-premium" : "")
                }
              >
                {planPriceLabel(PLAN_PRICING[plan].base)}
                {PLAN_PRICING[plan].base > 0 && <span>/mo</span>}
              </div>
              <p className="pricing-total">{planLoginLabel(plan)}</p>
              <p className="plan-card-estimate">
                {planMonthlyTotal(plan, loginCount)
                  ? `$${planMonthlyTotal(plan, loginCount)}/mo`
                  : "Free"}{" "}
                for your {loginCount} login
                {loginCount !== 1 ? "s" : ""}
              </p>
              <div className="plan-sync-line">
                <span className="badge-dot" aria-hidden="true"></span>
                {PLAN_SYNC[plan].label}
              </div>
              <ul className="plan-feature-list">
                {PLAN_FEATURES[plan].map((f, i) => (
                  <li key={i} className={f.endsWith("plus:") ? "plan-feature-lead" : ""}>
                    {f}
                  </li>
                ))}
              </ul>
              {rank > currentRank && (
                <button
                  className={plan === "premium" || recommended ? "btn-primary" : "btn-secondary"}
                  data-tour={plan === "premium" ? "upgrade-pro" : undefined}
                  disabled={!!requesting}
                  onClick={() => requestUpgrade(plan)}
                >
                  {requesting === plan ? "Sending…" : `Upgrade to ${planLabel(plan)}`}
                </button>
              )}
            </div>
          );
        })}
      </div>

      <h3 className="plans-section-title">Add-ons</h3>
      <div className="payroll-addon" data-tour="payroll-addon">
        <PayrollAddOnCard client={client} clientPortalUser={clientPortalUser} inPlanPage />
      </div>

      <div className="card plans-fine-print" style={{ marginBottom: 20 }}>
        <p>
          <strong>Moving to {PLAN_LABELS.basic}?</strong> It includes one
          login; any others stay at ${PLAN_PRICING.basic.perLogin}/mo each, or
          they're removed. Nobody loses their data.
        </p>
        <p style={{ marginBottom: 0 }}>
          <strong>QuickBooks sync:</strong> {PLAN_LABELS.basic}:{" "}
          {syncCadenceLabel("basic").replace("Synced from QuickBooks ", "")}.{" "}
          {PLAN_LABELS.premium}:{" "}
          {syncCadenceLabel("premium").replace("Synced from QuickBooks ", "")}, with a
          Sync now button.
        </p>
      </div>

      <h3 className="plans-section-title">What {PLAN_LABELS.premium} adds</h3>
      <div className="report-grid" style={{ marginBottom: 20 }}>
        {ENTERPRISE_FEATURES.map((f) => (
          <div className="card" key={f.title} data-tour={"pro-feature-" + f.key}>
            <div className="icon-badge">{f.icon}</div>
            <h3 className="card-title" style={{ marginTop: 14 }}>
              {f.title}
            </h3>
            <div className="enterprise-feature-tab-tag">{f.tag}</div>
            <p className="card-subtitle" style={{ marginBottom: 0 }}>
              {f.description}
            </p>
          </div>
        ))}
      </div>

      <div className="card" data-tour="pro-compare" style={{ marginBottom: 20 }}>
        <h3 className="card-title">
          {PLAN_LABELS.premium}, tool by tool
        </h3>
        <p className="card-subtitle">
          Click a tool to see exactly what you get.
        </p>
        <div className="compare-list">
          {ENTERPRISE_COMPARISON.map((c) => {
            const isOpen = openKey === c.key;
            return (
              <div
                className={"compare-row" + (isOpen ? " open" : "")}
                key={c.key}
              >
                <button
                  type="button"
                  className="compare-row-head"
                  onClick={() => setOpenKey(isOpen ? null : c.key)}
                  aria-expanded={isOpen}
                >
                  <span>{c.tool}</span>
                  {isOpen ? <ChevronUpIcon /> : <ChevronDownIcon />}
                </button>
                {/* Always mounted (not isOpen &&) so grid-template-rows can
                    animate both open and close. */}
                <div className="compare-row-body-wrap">
                  {/* One column: Basic doesn't have these tabs, so this is
                      the full list of what Pro gives you here (c.features). */}
                  <div className="compare-row-body compare-row-body-single">
                    <div className="compare-col compare-col-premium">
                      <div className="compare-col-header premium">
                        {c.tool}{" "}
                        <span className="nav-pro-pill">{PLAN_LABELS.premium}</span>
                      </div>
                      <p className="compare-feat-all">{c.intro}</p>
                      <ul className="compare-feat-list">
                        {c.features.map((f, i) => (
                          <li key={i}>{f}</li>
                        ))}
                      </ul>
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

// ----------------------------------------------------------------------------
// Budgeting Tool (client-editable draft budget, separate from the
// bookkeeper-maintained Budget vs. Actual report)
// ----------------------------------------------------------------------------

function BudgetingToolPage({ client }) {
  const [rows, setRows] = useState(() =>
    client.budget.map((b) => ({
      category: b.category,
      actual: b.actual,
      current: b.budgeted,
      proposed: b.budgeted,
    })),
  );
  const [newCategory, setNewCategory] = useState("");
  const showToast = useToast();

  const updateProposed = (index, value) => {
    const num = parseFloat(value);
    setRows((r) =>
      r.map((row, i) =>
        i === index ? { ...row, proposed: isNaN(num) ? 0 : num } : row,
      ),
    );
  };

  const removeRow = (index) => {
    setRows((r) => r.filter((_, i) => i !== index));
  };

  const addRow = () => {
    if (!newCategory.trim()) return;
    setRows((r) => [
      ...r,
      { category: newCategory.trim(), actual: 0, current: 0, proposed: 0 },
    ]);
    setNewCategory("");
  };

  const totalCurrent = rows.reduce((s, r) => s + r.current, 0);
  const totalProposed = rows.reduce((s, r) => s + r.proposed, 0);
  const pctChange =
    totalCurrent > 0
      ? ((totalProposed - totalCurrent) / totalCurrent) * 100
      : 0;

  const { flashCardId, jumpToCard } = useCardFlash();
  const jumpToDraft = () => jumpToCard("budgeting-tool-draft-card", "draft");

  return (
    <div>
      <MockBanner text="This is a working draft space — nothing here is saved anywhere real yet, and submitting doesn't notify anyone." />

      <div className="kpi-grid">
        <button
          className="card kpi-card kpi-card-clickable"
          onClick={jumpToDraft}
        >
          <span className="kpi-label">Current Budget Total</span>
          <span className="kpi-value">{fmtMoney(totalCurrent)}</span>
        </button>
        <button
          className="card kpi-card kpi-card-clickable"
          onClick={jumpToDraft}
        >
          <span className="kpi-label">Proposed Budget Total</span>
          <span className="kpi-value">{fmtMoney(totalProposed)}</span>
        </button>
        <button
          className="card kpi-card kpi-card-clickable"
          onClick={jumpToDraft}
        >
          <span className="kpi-label">Change</span>
          <span className="kpi-value">
            {(pctChange >= 0 ? "+" : "") + pctChange.toFixed(1)}%
          </span>
          <span className="kpi-sub neutral">vs. current budget</span>
        </button>
      </div>

      <div
        className={"card " + (flashCardId === "draft" ? "card-flash" : "")}
        id="budgeting-tool-draft-card"
        style={{ marginBottom: 20 }}
      >
        <h3 className="card-title">Draft Budget by Category</h3>
        <p className="card-subtitle">
          Adjust proposed amounts for next period. This year's actual is shown
          for reference.
        </p>
        <div className="table-scroll">
          <table className="tx-table tx-table-labeled">
            <thead>
              <tr>
                <th>Category</th>
                <th className="num">This Year's Actual</th>
                <th className="num">Current Budget</th>
                <th className="num">Proposed Budget</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r, i) => {
                // Same bullet-bar treatment as standard Budget vs. Actual's
                // Spending by Category: track spans whichever of current
                // budget/actual is bigger, fill is the real dollar amount, tick
                // marks the current budget line — against actual, not the
                // proposed number being drafted in this row.
                const scaleMax = Math.max(r.current, r.actual, 1) * 1.08;
                const fillPct = Math.min((r.actual / scaleMax) * 100, 100);
                const tickPct = Math.min((r.current / scaleMax) * 100, 100);
                const over = r.actual > r.current;
                return (
                  <tr key={i}>
                    <td data-primary="">
                      <div className="category-name">{r.category}</div>
                      <div className="bullet-track">
                        <div
                          className={"bullet-fill " + (over ? "over" : "under")}
                          style={{
                            width: `${fillPct}%`,
                            animationDuration: `${growDuration(fillPct)}ms`,
                          }}
                        ></div>
                        <div
                          className="bullet-target"
                          style={{ left: `${tickPct}%` }}
                        ></div>
                      </div>
                    </td>
                    <td className="num" data-label="This year's actual">
                      {fmtMoney(r.actual)}
                    </td>
                    <td className="num" data-label="Current budget">
                      {fmtMoney(r.current)}
                    </td>
                    <td className="num" data-label="Proposed budget">
                      <input
                        type="number"
                        className="budget-input"
                        value={r.proposed}
                        onChange={(e) => updateProposed(i, e.target.value)}
                      />
                    </td>
                    <td className="row-remove-cell">
                      <button
                        className="row-remove-btn"
                        onClick={() => removeRow(i)}
                        aria-label={`Remove ${r.category}`}
                      >
                        ×
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>

        <div className="add-category-row">
          <input
            type="text"
            placeholder="New category name…"
            value={newCategory}
            onChange={(e) => setNewCategory(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") addRow();
            }}
          />
          <button className="btn-secondary" onClick={addRow}>
            + Add Category
          </button>
        </div>

        <div className="budget-tool-footer">
          <span className="card-subtitle" style={{ margin: 0 }}>
            Total Proposed: {fmtMoney(totalProposed)}
          </span>
          <button
            className="btn-primary"
            onClick={() => {
              const filename = buildDraftBudgetPdf(client, rows);
              showToast(`Downloaded "${filename}"`);
            }}
          >
            Download PDF
          </button>
        </div>
      </div>

      {/* Budget vs. Actual (the standard page this one replaces for a
          premium client) has a Spending Trend toggle — the same
          multi-month income/expense chart the Dashboard uses. Shown here as
          a plain reference card rather than a toggle, since the draft table
          above is this page's whole reason to exist and shouldn't be
          hideable behind one — but the chart itself needs to stay reachable
          so this page is still a strict superset of Budget vs. Actual. */}
      <div className="card">
        <h3 className="card-title">Spending Trend</h3>
        <p className="card-subtitle">
          Income vs. expenses, last {client.monthly.length} months — for
          reference while drafting
        </p>
        <IncomeExpenseChart
          monthly={client.monthly}
          budgetTotal={totalCurrent}
        />
      </div>
    </div>
  );
}

// ----------------------------------------------------------------------------
// Cash Flow Pro — a bookkeeper-grade view of the same payables shown
// under Cash Flow: status filters, an aging summary, and a
// next-due list. Same client.payables array, not a second data set — see
// [[project-mock-data-inconsistencies]] on why nothing here should sum
// bankAccounts[].transactions instead.
// ----------------------------------------------------------------------------

const AP_SOON_DAYS = 7;

const AP_STATUS_META = {
  overdue: { label: "Overdue", pill: "bad" },
  soon: { label: "Due soon", pill: "warm" },
  scheduled: { label: "Scheduled", pill: "neutral" },
};

const AP_STATUS_FILTERS = [
  { key: "all", label: "All" },
  { key: "overdue", label: "Overdue" },
  { key: "soon", label: "Due soon" },
  { key: "scheduled", label: "Scheduled" },
];

function apDueText(diff) {
  if (diff < 0) return `${Math.abs(diff)}d overdue`;
  if (diff === 0) return "Due today";
  return `in ${diff}d`;
}

// QuickBooks' own aging report buckets (A/P and A/R Aging Summary), so the
// numbers here line up with what the bookkeeper sees in QuickBooks. `diff`
// is daysUntil(dueDate, today): negative means overdue.
const AP_AGING_BUCKETS = [
  { key: "current", label: "Current", test: (d) => d >= 0, color: "var(--good)" },
  { key: "d1_30", label: "1–30 days over", test: (d) => d < 0 && d >= -30, color: "var(--warm-text)" },
  { key: "d31_60", label: "31–60 days over", test: (d) => d < -30 && d >= -60, color: "var(--bad)" },
  { key: "d61_90", label: "61–90 days over", test: (d) => d < -60 && d >= -90, color: "var(--bad)" },
  { key: "d91plus", label: "91+ days over", test: (d) => d < -90, color: "var(--bad)" },
];
function apAging(rows) {
  return AP_AGING_BUCKETS.map((b) => ({
    ...b,
    amount: rows.filter((r) => b.test(r.diff)).reduce((s, r) => s + r.amount, 0),
  }));
}

// A CSV cell that starts with = + - @ (or a tab/CR) is run as a formula by
// Excel and Sheets; vendor and customer names come from QuickBooks, so
// prefix those with an apostrophe. Plain numbers (amounts) are left alone.
function apCsvCell(v) {
  let s = String(v == null ? "" : v);
  if (/^[=+\-@\t\r]/.test(s) && !/^-?\d+(\.\d+)?$/.test(s)) s = "'" + s;
  return `"${s.replace(/"/g, '""')}"`;
}

function APCommandCenterPage({ client }) {
  const [statusFilter, setStatusFilter] = useState("all");
  const [query, setQuery] = useState("");
  const [selected, setSelected] = useState(() => new Set());
  const [payRun, setPayRun] = useState(null); // { ids, total, status: "awaiting_approval" | "approved" }
  const today = todayLocal();
  const showToast = useToast();
  const { flashCardId, jumpToCard } = useCardFlash();
  const jumpToBills = (status) => {
    setStatusFilter(status);
    jumpToCard("ap-cc-open-bills-card", "open-bills");
  };

  const rows = useMemo(() => {
    return client.payables.map((p, i) => {
      const diff = daysUntil(p.dueDate, today);
      const status =
        diff < 0 ? "overdue" : diff <= AP_SOON_DAYS ? "soon" : "scheduled";
      return { ...p, diff, status, rowId: p.id != null ? p.id : i };
    });
  }, [client.payables, today]);

  // Same vendor + same amount showing up more than once usually means a bill
  // was entered twice, not that the vendor billed the same amount by chance.
  const duplicateRowIds = useMemo(() => {
    const seen = new Map();
    rows.forEach((r) => {
      const key = r.vendor + "|" + r.amount;
      seen.set(key, (seen.get(key) || []).concat(r.rowId));
    });
    const flagged = new Set();
    seen.forEach((ids) => {
      if (ids.length > 1) ids.forEach((id) => flagged.add(id));
    });
    return flagged;
  }, [rows]);

  const vendorSummary = useMemo(() => {
    const byVendor = new Map();
    rows.forEach((r) => {
      const v = byVendor.get(r.vendor) || {
        vendor: r.vendor,
        total: 0,
        count: 0,
        overdue: 0,
      };
      v.total += r.amount;
      v.count += 1;
      if (r.status === "overdue") v.overdue += 1;
      byVendor.set(r.vendor, v);
    });
    return [...byVendor.values()].sort((a, b) => b.total - a.total);
  }, [rows]);

  const byStatus = (key) =>
    rows.filter((r) => key === "all" || r.status === key);

  const totals = useMemo(() => {
    const sum = (list) => list.reduce((s, r) => s + r.amount, 0);
    return Object.fromEntries(
      ["all", "overdue", "soon", "scheduled"].map((key) => {
        const list = byStatus(key);
        return [key, { amount: sum(list), count: list.length }];
      }),
    );
  }, [rows]);

  const filteredRows = useMemo(() => {
    const q = query.trim().toLowerCase();
    return byStatus(statusFilter)
      .filter(
        (r) =>
          !q ||
          r.vendor.toLowerCase().includes(q) ||
          r.description.toLowerCase().includes(q),
      )
      .sort((a, b) => a.diff - b.diff);
  }, [rows, statusFilter, query]);

  const agingBuckets = useMemo(() => apAging(rows), [rows]);
  const maxBucket = Math.max(...agingBuckets.map((b) => b.amount), 1);

  // Receivables: the other half of cash flow, aged the same way.
  const arRows = useMemo(
    () =>
      (client.receivables || []).map((r, i) => ({
        ...r,
        diff: daysUntil(r.dueDate, today),
        rowId: r.id != null ? r.id : "ar" + i,
      })),
    [client.receivables, today],
  );
  const arAging = useMemo(() => apAging(arRows), [arRows]);
  const arMaxBucket = Math.max(...arAging.map((b) => b.amount), 1);
  const arTotal = arRows.reduce((s, r) => s + r.amount, 0);
  const arOverdue = arRows.filter((r) => r.diff < 0);
  const arOverdueTotal = arOverdue.reduce((s, r) => s + r.amount, 0);
  const arTop = useMemo(() => {
    const by = new Map();
    arRows.forEach((r) => {
      const name = r.customerName || r.description || "Customer";
      const v = by.get(name) || { name, total: 0, count: 0, overdue: 0 };
      v.total += r.amount;
      v.count += 1;
      if (r.diff < 0) v.overdue += 1;
      by.set(name, v);
    });
    return [...by.values()].sort((a, b) => b.total - a.total);
  }, [arRows]);
  // Nothing here pays a bill: the approval steps were a prototype. A live
  // (QuickBooks) client gets a plain "bills to pay" list and CSV instead.
  const isLive = client.dataSource === "quickbooks";

  const nextDue = useMemo(
    () => [...rows].sort((a, b) => a.diff - b.diff).slice(0, 5),
    [rows],
  );
  const shownTotal = filteredRows.reduce((s, r) => s + r.amount, 0);

  const toggleRow = (rowId) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(rowId)) next.delete(rowId);
      else next.add(rowId);
      return next;
    });
  };
  const allShownSelected =
    filteredRows.length > 0 && filteredRows.every((r) => selected.has(r.rowId));
  const toggleAllShown = () => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (allShownSelected) filteredRows.forEach((r) => next.delete(r.rowId));
      else filteredRows.forEach((r) => next.add(r.rowId));
      return next;
    });
  };

  const selectedRows = rows.filter((r) => selected.has(r.rowId));
  const selectedTotal = selectedRows.reduce((s, r) => s + r.amount, 0);
  const cashOnHand = totalCash(client);
  const cashAfterPayRun = cashOnHand - selectedTotal;

  const startPayRun = () => {
    if (selectedRows.length === 0) return;
    setPayRun({
      ids: [...selected],
      total: selectedTotal,
      status: "awaiting_approval",
    });
    showToast(
      `Pay run of ${selectedRows.length} bill${selectedRows.length !== 1 ? "s" : ""} (${fmtMoney(
        selectedTotal,
        {
          cents: true,
        },
      )}) sent for approval.`,
    );
  };
  const approvePayRun = () => {
    setPayRun((prev) => (prev ? { ...prev, status: "approved" } : prev));
    showToast("Pay run approved — ready to send to the bank.");
  };
  const cancelPayRun = () => {
    setPayRun(null);
    setSelected(new Set());
  };

  const exportPayRunCsv = () => {
    const list = payRun
      ? rows.filter((r) => payRun.ids.includes(r.rowId))
      : selectedRows;
    if (list.length === 0) return;
    const csvRows = [
      ["Vendor", "Description", "Amount", "Due Date"],
      ...list.map((r) => [
        r.vendor,
        r.description,
        r.amount.toFixed(2),
        r.dueDate,
      ]),
    ];
    const csv = csvRows.map((r) => r.map(apCsvCell).join(",")).join("\n");
    const blob = new Blob([csv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `${String(client.name || "bills").replace(/\s+/g, "_")}_${isLive ? "bills_to_pay" : "ACH_batch"}.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showToast(
      isLive
        ? `Exported ${list.length} bill${list.length !== 1 ? "s" : ""}. Pay them in QuickBooks or your bank.`
        : `Exported ${list.length} bill${list.length !== 1 ? "s" : ""} for bank upload.`,
    );
  };

  return (
    <div>
      <MockBanner text="These are the same sample payables shown under Cash Flow. Connect QuickBooks to replace this with live AP data."client={client} />

      <div className="kpi-grid">
        <button
          className="card kpi-card kpi-card-clickable"
          onClick={() => jumpToBills("all")}
        >
          <span className="kpi-label">Total Payable</span>
          <span className="kpi-value">{fmtMoney(totals.all.amount)}</span>
          <span className="kpi-sub neutral">
            {totals.all.count} open bill{totals.all.count !== 1 ? "s" : ""}
          </span>
        </button>
        <button
          className="card kpi-card kpi-card-clickable"
          onClick={() => jumpToBills("overdue")}
        >
          <span className="kpi-label">Overdue</span>
          <span className="kpi-value negative">
            {fmtMoney(totals.overdue.amount)}
          </span>
          <span className="kpi-sub negative">
            {totals.overdue.count} bill{totals.overdue.count !== 1 ? "s" : ""}{" "}
            past due
          </span>
        </button>
        <button
          className="card kpi-card kpi-card-clickable"
          onClick={() => jumpToBills("soon")}
        >
          <span className="kpi-label">Due Within {AP_SOON_DAYS} Days</span>
          <span className="kpi-value warm">{fmtMoney(totals.soon.amount)}</span>
          <span className="kpi-sub warm">
            {totals.soon.count} bill{totals.soon.count !== 1 ? "s" : ""}
          </span>
        </button>
        <button
          className="card kpi-card kpi-card-clickable"
          onClick={() => jumpToBills("scheduled")}
        >
          <span className="kpi-label">Scheduled</span>
          <span className="kpi-value">{fmtMoney(totals.scheduled.amount)}</span>
          <span className="kpi-sub neutral">
            {totals.scheduled.count} bill
            {totals.scheduled.count !== 1 ? "s" : ""}
          </span>
        </button>
        <button
          className="card kpi-card kpi-card-clickable"
          onClick={() => jumpToCard("ap-cc-ar-card", "ar-aging")}
        >
          <span className="kpi-label">Owed To You</span>
          <span className="kpi-value positive">{fmtMoney(arTotal)}</span>
          <span className={"kpi-sub " + (arOverdue.length ? "negative" : "neutral")}>
            {arRows.length} open invoice{arRows.length !== 1 ? "s" : ""}
            {arOverdue.length ? ` · ${arOverdue.length} overdue` : ""}
          </span>
        </button>
      </div>

      <div
        className={
          "card " + (flashCardId === "open-bills" ? "card-flash " : "")
        }
        id="ap-cc-open-bills-card"
        style={{ marginBottom: 20 }}
      >
        <div className="ap-cc-toolbar">
          <div>
            <h3 className="card-title">Open Bills</h3>
            <p className="card-subtitle">
              Every payable on file for {client.name}
            </p>
          </div>
          <div className="ap-cc-filters">
            <input
              className="ap-cc-search"
              type="text"
              placeholder="Search vendor or memo"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
            />
            <div className="rb-segmented ap-cc-segmented">
              {AP_STATUS_FILTERS.map((f) => (
                <button
                  key={f.key}
                  type="button"
                  aria-pressed={statusFilter === f.key}
                  onClick={() => setStatusFilter(f.key)}
                >
                  {f.label}
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="table-scroll">
          <table className="tx-table tx-table-labeled">
            <thead>
              <tr>
                <th style={{ width: 28 }}>
                  <input
                    type="checkbox"
                    checked={allShownSelected}
                    onChange={toggleAllShown}
                    aria-label="Select all shown bills"
                  />
                </th>
                <th>Vendor</th>
                <th>Status</th>
                <th className="num">Amount</th>
                <th>Due</th>
              </tr>
            </thead>
            <tbody>
              {filteredRows.map((r) => {
                const meta = AP_STATUS_META[r.status];
                return (
                  <tr key={r.rowId}>
                    <td>
                      <input
                        type="checkbox"
                        checked={selected.has(r.rowId)}
                        onChange={() => toggleRow(r.rowId)}
                        aria-label={`Select ${r.vendor} bill`}
                      />
                    </td>
                    <td data-primary="">
                      {r.vendor}
                      <div className="tx-meta">
                        {r.description}
                        {duplicateRowIds.has(r.rowId) && (
                          <span className="pill warm" style={{ marginLeft: 6 }}>
                            Possible duplicate
                          </span>
                        )}
                      </div>
                    </td>
                    <td data-label="Status">
                      <span className={"pill " + meta.pill}>{meta.label}</span>
                    </td>
                    <td className="num tx-amount negative" data-label="Amount">
                      -{fmtMoney(r.amount, { cents: true })}
                    </td>
                    <td data-label="Due">
                      {fmtDate(r.dueDate)}
                      <div
                        className={
                          "ap-cc-due-days" + (r.diff < 0 ? " overdue" : "")
                        }
                      >
                        {apDueText(r.diff)}
                      </div>
                    </td>
                  </tr>
                );
              })}
              {filteredRows.length === 0 && (
                <tr>
                  <td colSpan={5} className="ap-cc-empty">
                    No bills match this filter.
                  </td>
                </tr>
              )}
            </tbody>
            <tfoot>
              <tr>
                <td colSpan={3}>Total shown</td>
                <td className="num tx-amount negative">
                  -{fmtMoney(shownTotal, { cents: true })}
                </td>
                <td></td>
              </tr>
            </tfoot>
          </table>
        </div>
      </div>

      {(selected.size > 0 || payRun) && (
        <div className="card" style={{ marginBottom: 20 }}>
          <h3 className="card-title">{isLive ? "Bills to Pay" : "Pay Run"}</h3>
          {isLive && (
            <p className="card-subtitle">
              A planning list only. Nothing is paid or sent from here: pay these
              in QuickBooks or through your bank.
            </p>
          )}
          <p className="card-subtitle">
            {payRun
              ? `${payRun.ids.length} bill${payRun.ids.length !== 1 ? "s" : ""} · ${fmtMoney(
                  payRun.total,
                  {
                    cents: true,
                  },
                )}`
              : `${selectedRows.length} bill${selectedRows.length !== 1 ? "s" : ""} selected · ${fmtMoney(
                  selectedTotal,
                  { cents: true },
                )}`}
          </p>

          <div className="ap-cc-payrun-impact">
            <div>
              <span className="ap-cc-age-label">Cash on hand today</span>
              <div className="kpi-value" style={{ fontSize: 20 }}>
                {fmtMoney(cashOnHand, { cents: true })}
              </div>
            </div>
            <div>
              <span className="ap-cc-age-label">
                {isLive ? "Balance after paying these" : "Balance after this pay run"}
              </span>
              <div
                className={
                  "kpi-value " + (cashAfterPayRun < 0 ? "negative" : "")
                }
                style={{ fontSize: 20 }}
              >
                {fmtMoney(cashAfterPayRun, { cents: true })}
              </div>
            </div>
          </div>

          {payRun && (
            <div className="ap-cc-approval-row">
              <span
                className={
                  "pill " + (payRun.status === "approved" ? "good" : "warm")
                }
              >
                {payRun.status === "approved"
                  ? "Approved"
                  : "Awaiting Treasurer approval"}
              </span>
            </div>
          )}

          <div className="ap-cc-payrun-actions">
            {!payRun && !isLive && (
              <button
                className="btn-primary"
                onClick={startPayRun}
                disabled={selectedRows.length === 0}
              >
                Send for Approval
              </button>
            )}
            {payRun && payRun.status === "awaiting_approval" && (
              <button className="btn-primary" onClick={approvePayRun}>
                Approve Pay Run
              </button>
            )}
            <button
              className="btn-secondary"
              onClick={exportPayRunCsv}
              disabled={selectedRows.length === 0 && !payRun}
            >
              {isLive ? "Export List (CSV)" : "Export ACH Batch (CSV)"}
            </button>
            {isLive && !payRun && (
              <button className="btn-secondary" onClick={cancelPayRun}>
                Clear Selection
              </button>
            )}
            {payRun && (
              <button className="btn-secondary" onClick={cancelPayRun}>
                Clear Pay Run
              </button>
            )}
          </div>
        </div>
      )}

      <div className="content-masonry">
        <div className="card">
          <h3 className="card-title">Vendor Summary</h3>
          <p className="card-subtitle">Open balance by vendor</p>
          <div className="ap-cc-upcoming">
            {vendorSummary.slice(0, 6).map((v) => (
              <div className="ap-cc-upcoming-item" key={v.vendor}>
                <div>
                  <div className="ap-cc-upcoming-who">{v.vendor}</div>
                  <div className="ap-cc-upcoming-when">
                    {v.count} bill{v.count !== 1 ? "s" : ""}
                    {v.overdue > 0 ? ` · ${v.overdue} overdue` : ""}
                  </div>
                </div>
                <span className="ap-cc-upcoming-amt">
                  {fmtMoney(v.total, { cents: true })}
                </span>
              </div>
            ))}
            {vendorSummary.length === 0 && (
              <p className="card-subtitle">No open bills.</p>
            )}
          </div>
        </div>

        <div className="card">
          <h3 className="card-title">Payables Aging</h3>
          <p className="card-subtitle">Bills by how overdue they are</p>
          <div className="ap-cc-aging">
            {agingBuckets.map((b) => (
              <div className="ap-cc-age-row" key={b.key}>
                <span className="ap-cc-age-label">{b.label}</span>
                <span className="ap-cc-age-track">
                  <span
                    className="ap-cc-age-fill"
                    style={{
                      width: `${(b.amount / maxBucket) * 100}%`,
                      background: b.color,
                    }}
                  />
                </span>
                <span className="ap-cc-age-amt">{fmtMoney(b.amount)}</span>
              </div>
            ))}
          </div>
        </div>

        <div className="card">
          <h3 className="card-title">Next 5 Due</h3>
          <p className="card-subtitle">Coming up soonest</p>
          <div className="ap-cc-upcoming">
            {nextDue.map((r) => (
              <div className="ap-cc-upcoming-item" key={r.rowId}>
                <div>
                  <div className="ap-cc-upcoming-who">{r.vendor}</div>
                  <div className="ap-cc-upcoming-when">{apDueText(r.diff)}</div>
                </div>
                <span className="ap-cc-upcoming-amt">
                  {fmtMoney(r.amount, { cents: true })}
                </span>
              </div>
            ))}
            {nextDue.length === 0 && (
              <p className="card-subtitle">No open bills.</p>
            )}
          </div>
        </div>

        <div
          className={"card " + (flashCardId === "ar-aging" ? "card-flash" : "")}
          id="ap-cc-ar-card"
        >
          <h3 className="card-title">Receivables Aging</h3>
          <p className="card-subtitle">
            {fmtMoney(arTotal)} owed to you
            {arOverdue.length > 0
              ? ` · ${fmtMoney(arOverdueTotal)} overdue`
              : ""}
          </p>
          {arRows.length === 0 ? (
            <p className="card-subtitle">No open invoices.</p>
          ) : (
            <div className="ap-cc-aging">
              {arAging.map((b) => (
                <div className="ap-cc-age-row" key={b.key}>
                  <span className="ap-cc-age-label">{b.label}</span>
                  <span className="ap-cc-age-track">
                    <span
                      className="ap-cc-age-fill"
                      style={{
                        width: `${(b.amount / arMaxBucket) * 100}%`,
                        background: b.color,
                      }}
                    />
                  </span>
                  <span className="ap-cc-age-amt">{fmtMoney(b.amount)}</span>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="card">
          <h3 className="card-title">Who Owes You</h3>
          <p className="card-subtitle">Open invoices by customer</p>
          <div className="ap-cc-upcoming">
            {arTop.slice(0, 6).map((v) => (
              <div className="ap-cc-upcoming-item" key={v.name}>
                <div>
                  <div className="ap-cc-upcoming-who">{v.name}</div>
                  <div className="ap-cc-upcoming-when">
                    {v.count} invoice{v.count !== 1 ? "s" : ""}
                    {v.overdue > 0 ? ` · ${v.overdue} overdue` : ""}
                  </div>
                </div>
                <span className="ap-cc-upcoming-amt">
                  {fmtMoney(v.total, { cents: true })}
                </span>
              </div>
            ))}
            {arTop.length === 0 && (
              <p className="card-subtitle">No open invoices.</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

// ----------------------------------------------------------------------------
// Staff Access (admin only) — manage who can sign in to the portal at all.
// Reads/writes the real `staff` table in Supabase directly (not mock data).
// Authorization is enforced by Postgres RLS (see
// supabase/staff-admin-policies.sql), not by this component: a non-admin who
// somehow rendered this page would still have every request rejected by the
// database, since only an active admin's own row satisfies the write policy.
// ----------------------------------------------------------------------------

const STAFF_ROLES = ["bookkeeper", "admin"];

const STAFF_AUDIT_VERBS = {
  added: "added",
  removed: "removed",
  role_changed: "changed the role of",
  activated: "reactivated",
  deactivated: "deactivated",
  // Written by the staff-auth edge function, not the staff trigger.
  auth_user_created: "set up Google sign-in for",
  auth_repair: "ran Fix sign-in for",
};

function staffAuditVerb(action) {
  return STAFF_AUDIT_VERBS[action] || action;
}

// Supabase Auth has new sign-ups switched off, so a staff row alone isn't
// enough for Google sign-in: the person also needs a sign-in account
// (auth.users row). supabase/functions/staff-auth makes it (admins only,
// active @mygoodbooks.org staff only). body: { action: "ensure", emails }
// or { action: "repair" }. Resolves { ok, results, summary, message } and
// never throws.
const STAFF_AUTH_REASONS = {
  invalid_email: "not a mygoodbooks.org address",
  not_staff: "not on the staff list",
  not_active_staff: "deactivated",
  ambiguous: "listed twice on the staff list",
  client_login: "already a client portal login",
  rate_limited: "hourly limit reached, try again later",
  create_failed: "setup failed",
};

// Toast for one person whose sign-in account wasn't made. `verb` is
// "Added" / "Reactivated". Fix sign-in can't help with a client login or a
// deactivated row, so those get their own wording.
function staffAuthFailMessage(verb, name, failure) {
  const reason = failure && failure.reason;
  if (reason === "client_login")
    return `${verb} ${name}, but that address is already a client portal login, so it can't also sign in as staff. Use a different address.`;
  if (reason === "not_active_staff")
    return `${verb} ${name}, but they're deactivated, so no sign-in was set up. Reactivate them first.`;
  if (reason === "rate_limited")
    return `${verb} ${name}, but the hourly sign-in limit is reached. Use Fix sign-in in an hour.`;
  return `${verb} ${name}, but sign-in setup failed — use Fix sign-in.`;
}

async function staffAuthInvoke(supabase, body) {
  if (!supabase) return { ok: false, results: [], message: "Supabase isn't configured." };
  try {
    const { data, error } = await supabase.functions.invoke("staff-auth", { body });
    if (error) {
      // FunctionsHttpError keeps the JSON body on .context (same as
      // inviteContact): show the endpoint's friendly message.
      let message = error.message;
      try {
        const b = await error.context.json();
        if (b && (b.message || b.error)) message = b.message || b.error;
      } catch (_) {
        /* non-JSON body — keep error.message */
      }
      return { ok: false, results: [], message };
    }
    const results = (data && data.results) || [];
    return { ok: true, results, summary: (data && data.summary) || {}, more: (data && data.more) || 0 };
  } catch (e) {
    return { ok: false, results: [], message: (e && e.message) || "Network error" };
  }
}

// [{ email, reason }] for addresses in `emails` that did NOT end up with a
// sign-in account ("skipped" and "error" both count as failures).
function staffAuthFailures(res, emails) {
  if (!res.ok) return emails.map((email) => ({ email, reason: "request_failed" }));
  const byEmail = new Map(res.results.map((r) => [r.email, r]));
  const out = [];
  for (const email of emails) {
    const r = byEmail.get(String(email).toLowerCase());
    if (r && (r.status === "created" || r.status === "exists")) continue;
    out.push({ email, reason: (r && r.reason) || "request_failed" });
  }
  return out;
}

// Parses pasted CSV for bulk staff import: email,name,role per line, with an
// optional header row (detected by its first field not being an email) and
// blank lines skipped. Deliberately tiny — no quoted-field/embedded-comma
// support — since this is for pasting out of a simple roster spreadsheet,
// not accepting arbitrary CSV exports.
function parseStaffCsv(text) {
  const lines = text
    .split(/\r?\n/)
    .map((l) => l.trim())
    .filter(Boolean);
  const rows = [];
  lines.forEach((line, i) => {
    const [rawEmail, rawName, rawRole] = line
      .split(",")
      .map((f) => (f || "").trim());
    if (i === 0 && rawEmail && !rawEmail.includes("@")) return; // header row
    const email = (rawEmail || "").toLowerCase();
    const name = rawName || "";
    const role = STAFF_ROLES.includes((rawRole || "").toLowerCase())
      ? rawRole.toLowerCase()
      : "bookkeeper";
    const errors = [];
    if (!email || !email.includes("@")) errors.push("missing/invalid email");
    else if (!email.endsWith("@mygoodbooks.org"))
      errors.push("must be a mygoodbooks.org address");
    if (!name) errors.push("missing name");
    rows.push({ line, email, name, role, errors });
  });
  return rows;
}

// Cleared by Developer Tools' "Reset local state" button. Everything this
// matches is a per-browser viewer preference (theme, tab layout, dashboard/
// Live Report widget layouts, cash-floor alerts, per-client-user access
// overrides, ...), never anything from Supabase, so clearing it can't lose
// real data — only whatever local customization got the browser stuck.
//
// Previously an explicit list of keys, which meant every new feature that
// added its own localStorage key (the cash-floor alert, Live Report's own
// widget layout, ...) had to remember to also add itself here — easy to
// forget, and forgetting it silently makes "reset local state" a lie for
// that one feature. Matching everything under the shared "mygoodbooks_"
// prefix closes that gap for whatever gets added next, without needing to
// touch this function again. Feature flags (mygoodbooks_ff_*) are
// deliberately excluded — they're their own toggles right next to this
// button, not "local state" in the sense this reset is for.
function resettableLocalStorageKeys() {
  try {
    // Both key families: the original "mygoodbooks_" keys and the newer
    // "mgb-"/"mgb_" ones (nav, tour, tips, profile prompt, bell, client
    // switcher, inbox context, the Desk's mgb_wb_hub:<email>,
    // mgb_wb_pins:<email> and its width mgb_wb_desk:<email>, and the staff
    // sidebar choice mgb_rail_expanded:<email>, and the L1 left sidebar's
    // mgb_nav_prefs:<email> and mgb_nav_on_cache, and Slate's saved view
    // mgb_tk_slate_view_v1:<email> / :desk:<email>, and Slate Settings mgb_tk_prefs_v1:<email>: quick keys, density, open in, show older). Feature flags are kept on purpose, including
    // the ones without the mygoodbooks_ff_ prefix (mgb_wb_classic,
    // mgb_lato_classic, mgb_brand_classic, mgb_hovernav_classic, mgb_rhythm_preview,
    // mgb_slate_app_preview, mgb_slate_classic, mgb_nav_classic). The retired personal previews
    // (mgb_wb_preview, mgb_nav_preview, mgb_lato_preview, mgb_brand_preview, mgb_hovernav_preview,
    // retired 2026-10-25 once their firm switches were on for everyone) are no longer flags and nothing
    // reads them; a stale copy in a browser is cleared by Reset local state like any other mgb_ key. The Slate app's own keys (all start with mgb_ so Reset local state
    // clears them; none holds anything but a per-browser convenience): mgb_slate_app_preview (a flag, kept),
    // mgb_slate_classic (opt-out, a flag, kept), mgb_slate_cache (the firm switch as last read, set by index.html, cleared by Reset), mgb_rhythm_cache (month_rhythm_enabled as last read, set by index.html in the same read; TK_rhythmEnabled and the month-rhythm-launch notice use it until TK_rhythmLoad reads the switch; cleared by Reset), mgb_slate_installed_v1 (set when the app is installed),
    // mgb_tk_slate_base_v1 (the Default saved-view baseline), mgb_tk_manual_v1 (Manual order on or off per list),
    // mgb_tk_layout_v1 (List or Board per list, P1), and sessionStorage mgb_slate_size_miss_v1 (size presets hidden
    // this session after a resize miss; sessionStorage is not touched by Reset).
    // Client org profile (hidden preview): mgb_orgprofile_preview (a flag, kept),
    // mgb_orgprofile_cache (the firm switch as last read by OP_store, cleared by Reset),
    // mgb_orgprofile_client_cache (a client's last-known gate, holds the client tour; cleared by Reset),
    // and sessionStorage mgb_op_later:<email> (the client's "Later" for this sign-in; not touched by Reset).
    // Desk additions (hidden preview): mgb_deskplus_preview (a flag, kept),
    // mgb_deskplus_cache (the firm switch deskplus_enabled as last read by WB_plus.js, cleared by Reset).
    // Thread menu (hidden preview): mgb_threadmenu_preview (a flag, kept),
    // mgb_threadmenu_cache (the firm switch threadmenu_enabled as last read by TM_gate.js, cleared by Reset).
    return Object.keys(localStorage).filter(
      (k) =>
        (k.startsWith("mygoodbooks_") || k.startsWith("mgb-") || k.startsWith("mgb_")) &&
        !k.startsWith("mygoodbooks_ff_") &&
        !FEATURE_FLAGS.some((f) => f.key === k),
    );
  } catch (e) {
    return [];
  }
}

// Preset durations offered when an admin grants a bookkeeper temporary
// access to the three admin-only pages. Kept short — this is meant for
// "cover for me this afternoon", not a standing role change.
const TEMP_ACCESS_DURATIONS = [
  { label: "1 hour", ms: 60 * 60 * 1000 },
  { label: "1 day", ms: 24 * 60 * 60 * 1000 },
  { label: "1 week", ms: 7 * 24 * 60 * 60 * 1000 },
];

function formatTempAccessExpiry(isoString) {
  try {
    return new Date(isoString).toLocaleString(undefined, {
      month: "short",
      day: "numeric",
      hour: "numeric",
      minute: "2-digit",
    });
  } catch (e) {
    return isoString;
  }
}

// HR › Members "Last seen" (admins only; staff_last_seen in
// supabase/view-as-last-seen.sql refuses anyone else, temporary admins
// included). Last page view, last sign-in and last reported error for one
// person, to answer "did they get the update?" and "what broke for them?".
// Every value comes from that person's own browser, so it is shown as plain
// text only. The admin's own View as activity is left out server-side.
function SA_ago(iso) {
  if (!iso) return "";
  const ms = Date.now() - new Date(iso).getTime();
  if (!(ms >= 0)) return "just now";
  const mins = Math.floor(ms / 60000);
  if (mins < 1) return "just now";
  if (mins < 60) return `${mins} min ago`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours} hour${hours === 1 ? "" : "s"} ago`;
  const days = Math.floor(hours / 24);
  return `${days} day${days === 1 ? "" : "s"} ago`;
}

function SA_when(iso) {
  if (!iso) return "";
  const full = typeof fmtDateTime === "function" ? fmtDateTime(iso) : new Date(iso).toLocaleString();
  return `${SA_ago(iso)} (${full})`;
}

function SA_LastSeenDialog({ row, onClose }) {
  const [st, setSt] = useState({ loading: true, data: null, error: "" });
  useEffect(() => {
    let alive = true;
    const sb = window.mgbSupabase;
    if (!sb) {
      setSt({ loading: false, data: null, error: "Supabase isn't configured." });
      return undefined;
    }
    sb.rpc("staff_last_seen", { p_email: row.email }).then(({ data, error }) => {
      if (!alive) return;
      if (error) {
        const missing = typeof isMissingTableError === "function" && isMissingTableError(error);
        setSt({
          loading: false,
          data: null,
          error: missing ? "Last seen isn't set up yet (supabase/view-as-last-seen.sql)." : `Couldn't load: ${error.message}`,
        });
        return;
      }
      setSt({ loading: false, data: data || {}, error: "" });
    });
    return () => {
      alive = false;
    };
  }, [row.email]);

  const d = st.data || {};
  const v = d.last_view || null;
  const err = d.last_error || null;
  const current = window.MGB_VERSION && window.MGB_VERSION.label;
  const behind = !!(v && v.app_version && current && v.app_version !== current);
  const errBrowser = err && err.user_agent && typeof MGB_parseBrowser === "function" ? MGB_parseBrowser(err.user_agent) : "";
  const deviceLabel = (k) => (typeof USAGE_DEVICE_LABELS === "object" && USAGE_DEVICE_LABELS[k]) || k || "";
  const errorsWeek = Number(d.errors_7d || 0);

  return (
    <ModalShell onClose={onClose} labelledBy="sa-last-seen-title" className="sa-last-seen">
      <div className="modal-header">
        <h3 className="card-title" id="sa-last-seen-title" style={{ margin: 0 }}>
          Last seen: {row.name || row.email}
        </h3>
        <button className="modal-close" onClick={onClose} aria-label="Close">
          ×
        </button>
      </div>
      {st.loading ? (
        <p className="card-subtitle">Loading…</p>
      ) : st.error ? (
        <p className="card-subtitle" role="alert">
          {st.error}
        </p>
      ) : (
        <dl className="staff-info-list">
          <div>
            <dt>Last active</dt>
            <dd>
              {v ? (
                <>
                  {SA_when(v.occurred_at)}
                  <br />
                  {[v.page, v.tab].filter(Boolean).join(" › ") || "Unknown page"}
                  {[deviceLabel(v.device), v.browser].filter(Boolean).length
                    ? " · " + [deviceLabel(v.device), v.browser].filter(Boolean).join(" · ")
                    : ""}
                  <br />
                  Version {v.app_version || "unknown"}
                  {behind && (
                    <span className="sa-behind-pill" title={`The current version is ${current}. A reload picks it up.`}>
                      behind
                    </span>
                  )}
                </>
              ) : d.last_action_at ? (
                SA_when(d.last_action_at)
              ) : (
                "No activity recorded yet"
              )}
            </dd>
          </div>
          <div>
            <dt>Last sign-in</dt>
            <dd>{d.last_sign_in_at ? SA_when(d.last_sign_in_at) : "Never signed in"}</dd>
          </div>
          <div>
            <dt>Last error</dt>
            <dd>
              {err ? (
                <>
                  {SA_when(err.created_at)}
                  {err.page ? " · " + err.page : ""}
                  <span className="sa-err-msg">{String(err.message || "").slice(0, 200)}</span>
                  {[err.source, err.app_version ? "version " + err.app_version : "", errBrowser].filter(Boolean).join(" · ")}
                  <br />
                  {errorsWeek} error{errorsWeek === 1 ? "" : "s"} in the last 7 days.{" "}
                  <button
                    type="button"
                    className="link-btn"
                    onClick={() => {
                      onClose();
                      if (typeof NAV_go === "function") NAV_go("developer-tools");
                      else window.location.hash = "#/developer-tools";
                    }}
                  >
                    Open Recent errors
                  </button>
                </>
              ) : (
                "No errors reported"
              )}
            </dd>
          </div>
        </dl>
      )}
    </ModalShell>
  );
}

function SA_LastSeenButton({ row }) {
  const [open, setOpen] = useState(false);
  return (
    <>
      <button
        type="button"
        className="btn-secondary sa-last-seen-btn"
        data-tour="members-last-seen"
        onClick={() => {
          setOpen(true);
          if (typeof MGB_track === "function") MGB_track("last-seen", "open");
        }}
      >
        Last seen
      </button>
      {open && <SA_LastSeenDialog row={row} onClose={() => setOpen(false)} />}
    </>
  );
}

function StaffAccessPage({ staffUser, onImpersonate, readOnly }) {
  const showToast = useToast();
  const supabase = window.mgbSupabase;

  const [rows, setRows] = useState(null); // null while loading
  const [loadError, setLoadError] = useState("");
  const [busyId, setBusyId] = useState(null);
  const [newEmail, setNewEmail] = useState("");
  const [newName, setNewName] = useState("");
  const [newRole, setNewRole] = useState("bookkeeper");
  const [adding, setAdding] = useState(false);
  const [clientAccessFor, setClientAccessFor] = useState(null); // the staff row being edited, or null
  const [clientAccessSet, setClientAccessSet] = useState(new Set());
  const [clientAccessLoading, setClientAccessLoading] = useState(false);
  const [csvText, setCsvText] = useState("");
  const [csvImporting, setCsvImporting] = useState(false);
  const [csvResults, setCsvResults] = useState(null); // per-row outcome after an import run
  // email -> { expires_at, granted_by, reason } for anyone with a live temp
  // admin-access grant. Loaded alongside the roster; refreshed after any
  // grant/revoke.
  const [tempAccessMap, setTempAccessMap] = useState({});
  const [tempAccessDurationFor, setTempAccessDurationFor] = useState({}); // row.id -> selected ms
  const [tempAccessBusyId, setTempAccessBusyId] = useState(null);

  // Profile photos (components/staff/StaffPhotoAdmin.jsx, supabase/staff-photo.sql).
  // The list RPC is admin-only: for a temp admin it errors, rows stay null and
  // the Photo column shows a dash. Only a real admin (canActPhotos) gets
  // downloads, Replace, Restore, Not required and History.
  const canSeePhotos = typeof SP_useAdminList === "function";
  const spList = canSeePhotos ? SP_useAdminList(true) : { loaded: false, rows: null };
  const spByEmail = useMemo(() => {
    const m = {};
    (spList.rows || []).forEach((r) => {
      m[String(r.email).toLowerCase()] = r;
    });
    return m;
  }, [spList.rows]);
  const canActPhotos = staffUser.role === "admin" && !readOnly;
  const [photoEmail, setPhotoEmail] = useState(null); // whose photo drawer is open

  // Today's "N profile photos to edit" item sends the admin here with a
  // sessionStorage flag (the hash query is claimed by DeepLink.jsx): open the
  // first person whose photo needs an edit.
  useEffect(() => {
    if (!canActPhotos || !spList.rows) return;
    let flag = null;
    try {
      flag = window.sessionStorage.getItem("mgb-photo-open");
    } catch (e) {}
    if (flag !== "needs-edit") return;
    try {
      window.sessionStorage.removeItem("mgb-photo-open");
    } catch (e) {}
    const first = spList.rows.find((r) => r.active && r.status === "submitted");
    if (!first) return;
    setPhotoEmail(first.email);
    setTimeout(() => {
      try {
        const el = document.querySelector('[data-photo-row="' + String(first.email).toLowerCase() + '"]');
        if (el && el.scrollIntoView) el.scrollIntoView({ block: "center" });
      } catch (e) {}
    }, 80);
  }, [canActPhotos, spList.rows, rows]);

  // MGB (internal) grants, owner only. internal_access holds one row per
  // admin who may open it; the owner can read every row, so a non-owner never
  // sees this column. Writes go through the owner-only set_internal_access().
  // Test clients: last in the client-access list, tagged, hidden unless "Show test clients" is on (checked ones always stay).
  const [cfShowTest] = CF_useShowTest(window.mgbViewerEmail);
  const isInternalOwner = !!(staffUser && staffUser.isInternalOwner) && !readOnly;
  const [internalGrants, setInternalGrants] = useState({}); // email -> { is_owner }
  const [internalBusyId, setInternalBusyId] = useState(null);

  const loadInternalGrants = useCallback(() => {
    if (!supabase || !isInternalOwner) return;
    supabase
      .from("internal_access")
      .select("staff_email, is_owner")
      .then(({ data, error }) => {
        if (error) {
          console.warn("Couldn't load MGB (internal) access:", error.message);
          return;
        }
        const map = {};
        (data || []).forEach((r) => {
          map[String(r.staff_email).toLowerCase()] = r;
        });
        setInternalGrants(map);
      });
  }, [supabase, isInternalOwner]);

  useEffect(() => {
    loadInternalGrants();
  }, [loadInternalGrants]);

  async function toggleInternalAccess(row, allowed) {
    setInternalBusyId(row.id);
    const { error } = await supabase.rpc("set_internal_access", {
      p_email: row.email,
      p_allowed: allowed,
    });
    setInternalBusyId(null);
    if (error) {
      showToast(`Couldn't change MGB (internal) access: ${error.message}`);
      return;
    }
    showToast(
      allowed
        ? `${row.name} can now open MGB (internal).`
        : `${row.name} can no longer open MGB (internal).`,
    );
    loadInternalGrants();
  }

  const loadTempAccess = useCallback(() => {
    if (!supabase) return;
    supabase
      .from("staff_temp_admin_access")
      .select("staff_email, granted_by, granted_at, expires_at, reason")
      .then(({ data, error }) => {
        if (error) {
          // Most likely: staff-temp-admin-access.sql hasn't been run yet.
          // Fail quiet — this is a bonus capability, not core roster access.
          console.warn("Couldn't load temp admin access:", error.message);
          return;
        }
        const map = {};
        (data || []).forEach((r) => {
          map[r.staff_email] = r;
        });
        setTempAccessMap(map);
      });
  }, [supabase]);

  useEffect(() => {
    loadTempAccess();
  }, [loadTempAccess]);

  async function grantTempAccess(row) {
    const ms = tempAccessDurationFor[row.id] || TEMP_ACCESS_DURATIONS[0].ms;
    const expiresAt = new Date(Date.now() + ms).toISOString();
    setTempAccessBusyId(row.id);
    const { error } = await supabase.from("staff_temp_admin_access").upsert({
      staff_email: row.email,
      granted_by: staffUser.email,
      granted_at: new Date().toISOString(),
      expires_at: expiresAt,
    });
    setTempAccessBusyId(null);
    if (error) {
      showToast(`Couldn't grant temporary access: ${error.message}`);
      return;
    }
    showToast(`Granted ${row.name} temporary admin-page access.`);
    loadTempAccess();
  }

  async function revokeTempAccess(row) {
    setTempAccessBusyId(row.id);
    const { error } = await supabase
      .from("staff_temp_admin_access")
      .delete()
      .eq("staff_email", row.email);
    setTempAccessBusyId(null);
    if (error) {
      showToast(`Couldn't revoke temporary access: ${error.message}`);
      return;
    }
    showToast(`Revoked ${row.name}'s temporary admin-page access.`);
    loadTempAccess();
  }

  const csvPreview = useMemo(
    () => (csvText.trim() ? parseStaffCsv(csvText) : []),
    [csvText],
  );
  const csvValidCount = csvPreview.filter((r) => r.errors.length === 0).length;

  function openClientAccess(row) {
    setClientAccessFor(row);
    setClientAccessLoading(true);
    supabase
      .from("staff_client_access")
      .select("client_id")
      .eq("staff_email", row.email)
      .then(({ data, error }) => {
        setClientAccessLoading(false);
        if (error) {
          showToast(
            `Couldn't load ${row.name}'s client access: ${error.message}`,
          );
          setClientAccessFor(null);
          return;
        }
        setClientAccessSet(new Set(data.map((r) => r.client_id)));
      });
  }

  async function toggleClientAccess(clientId) {
    const wasChecked = clientAccessSet.has(clientId);
    const { error } = wasChecked
      ? await supabase
          .from("staff_client_access")
          .delete()
          .eq("staff_email", clientAccessFor.email)
          .eq("client_id", clientId)
      : await supabase
          .from("staff_client_access")
          .insert({ staff_email: clientAccessFor.email, client_id: clientId });
    if (error) {
      showToast(`Couldn't update client access: ${error.message}`);
      return;
    }
    setClientAccessSet((prev) => {
      const next = new Set(prev);
      if (wasChecked) next.delete(clientId);
      else next.add(clientId);
      return next;
    });
  }

  // Active staff with no sign-in account yet (staff_missing_auth(),
  // supabase/staff-auth-repair.sql). Admins only; hidden silently if the RPC
  // errors (migration not applied, or not a real admin). Refreshed by load().
  const [missingAuth, setMissingAuth] = useState(null);
  const [fixingAuth, setFixingAuth] = useState(false);
  const loadMissingAuth = useCallback(() => {
    if (!supabase || readOnly) return;
    supabase.rpc("staff_missing_auth").then(({ data, error }) => {
      setMissingAuth(error ? null : data || []);
    });
  }, [supabase, readOnly]);

  const load = useCallback(() => {
    if (!supabase) {
      setLoadError("Supabase isn't configured — see auth-config.js.");
      setRows([]);
      return;
    }
    loadMissingAuth();
    supabase
      .from("staff")
      .select("id, email, name, role, active, created_at")
      .order("created_at", { ascending: true })
      .then(({ data, error }) => {
        if (error) {
          // Most likely cause: supabase/staff-admin-policies.sql hasn't been
          // run yet, so only your own row is readable, not the full roster.
          setLoadError("Couldn't load the staff list. " + error.message);
          setRows([]);
        } else {
          setLoadError("");
          setRows(data);
        }
      });
  }, [supabase, loadMissingAuth]);

  useEffect(() => {
    load();
  }, [load]);

  const missingAuthSet = useMemo(
    () => new Set((missingAuth || []).map((m) => String(m.email).toLowerCase())),
    [missingAuth],
  );

  // Make the sign-in account for people just added/reactivated. Returns
  // [{ email, reason }] for those who still can't sign in (empty when all
  // went through).
  async function ensureSignIn(emails) {
    const failed = [];
    for (let i = 0; i < emails.length; i += 50) {
      const chunk = emails.slice(i, i + 50);
      const res = await staffAuthInvoke(supabase, { action: "ensure", emails: chunk });
      failed.push(...staffAuthFailures(res, chunk));
    }
    loadMissingAuth();
    return failed;
  }

  async function fixSignIn() {
    setFixingAuth(true);
    const res = await staffAuthInvoke(supabase, { action: "repair" });
    setFixingAuth(false);
    if (!res.ok) {
      showToast(`Couldn't fix sign-in: ${res.message}`);
    } else {
      const created = (res.summary && res.summary.created) || 0;
      const problems = res.results.filter((r) => r.status !== "created" && r.status !== "exists");
      const parts = [];
      if (created > 0)
        parts.push(`Sign-in fixed for ${created} ${created === 1 ? "person" : "people"}. They can sign in with Google now.`);
      if (problems.length)
        parts.push(
          "Not fixed: " +
            problems.map((r) => `${r.email} (${STAFF_AUTH_REASONS[r.reason] || r.reason || "setup failed"})`).join(", ") +
            ".",
        );
      if (res.more > 0)
        parts.push(`${res.more} more still ${res.more === 1 ? "needs" : "need"} it: run Fix sign-in again for the rest.`);
      if (parts.length === 0) parts.push("Nothing to fix: everyone active can already sign in.");
      showToast(parts.join(" "));
    }
    loadMissingAuth();
  }

  async function addStaff() {
    const email = newEmail.trim().toLowerCase();
    const name = newName.trim();
    if (!email || !name) return;
    if (!email.endsWith("@mygoodbooks.org")) {
      showToast(
        "Staff email must be a mygoodbooks.org address — Google sign-in will reject anything else.",
      );
      return;
    }
    setAdding(true);
    const { error } = await supabase
      .from("staff")
      .insert({ email, name, role: newRole, active: true });
    if (error) {
      setAdding(false);
      showToast(`Couldn't add ${email}: ${error.message}`);
      return;
    }
    setNewEmail("");
    setNewName("");
    setNewRole("bookkeeper");
    // The row stays even if this fails; the Fix sign-in card picks it up.
    const failed = await ensureSignIn([email]);
    setAdding(false);
    showToast(
      failed.length
        ? staffAuthFailMessage("Added", name, failed[0])
        : `Added ${name} to the staff list. They can sign in with Google now.`,
    );
    load();
  }

  async function importCsv() {
    const validRows = csvPreview.filter((r) => r.errors.length === 0);
    if (validRows.length === 0) return;
    setCsvImporting(true);
    // One insert per row, not a single batch insert, so one bad row (a typo'd
    // duplicate email, most likely) doesn't fail the whole import — matches
    // how addStaff() already reports failures per person.
    const results = [];
    for (const r of validRows) {
      const { error } = await supabase
        .from("staff")
        .insert({ email: r.email, name: r.name, role: r.role, active: true });
      results.push({
        email: r.email,
        name: r.name,
        ok: !error,
        message: error ? error.message : "",
      });
    }
    // One staff-auth call for everyone who went in (chunks of 50).
    const added = results.filter((r) => r.ok).map((r) => r.email);
    const signInFailed = new Map(
      (added.length ? await ensureSignIn(added) : []).map((f) => [f.email, f]),
    );
    results.forEach((r) => {
      if (r.ok && signInFailed.has(r.email)) r.signInFailed = signInFailed.get(r.email);
    });
    setCsvImporting(false);
    setCsvResults(results);
    const okCount = results.filter((r) => r.ok).length;
    showToast(
      signInFailed.size
        ? `Imported ${okCount} of ${results.length}, but sign-in wasn't set up for ${signInFailed.size} — see the results below.`
        : okCount === results.length
          ? `Imported ${okCount} staff.`
          : `Imported ${okCount} of ${results.length} — see the results below for what failed.`,
    );
    if (okCount === results.length) setCsvText("");
    load();
  }

  // Birthday + start date live on staff_profiles (Settings › Profile for the
  // person; admins can fill them here). Refetched whenever the roster loads.
  const [profiles, setProfiles] = useState({});
  useEffect(() => {
    if (!supabase || !rows || rows.length === 0) return;
    supabase
      .from("staff_profiles")
      .select("email, birthday, start_date")
      .then(({ data }) => {
        const m = {};
        (data || []).forEach((p) => (m[p.email] = p));
        setProfiles(m);
      });
  }, [supabase, rows]);
  async function updateProfile(row, patch) {
    const { error } = await supabase.from("staff_profiles").upsert({ email: row.email, ...patch }, { onConflict: "email" });
    if (error) {
      showToast(`Couldn't save ${row.email}: ${error.message}`);
      return;
    }
    setProfiles((p) => ({ ...p, [row.email]: { ...(p[row.email] || {}), ...patch } }));
    showToast("Saved");
  }

  async function updateRow(row, patch) {
    setBusyId(row.id);
    const { error } = await supabase
      .from("staff")
      .update(patch)
      .eq("id", row.id);
    if (error) {
      setBusyId(null);
      showToast(`Couldn't update ${row.email}: ${error.message}`);
      return;
    }
    if (patch.active === true) {
      const failed = await ensureSignIn([row.email]);
      if (failed.length) showToast(staffAuthFailMessage("Reactivated", row.name, failed[0]));
    }
    // Cleared only now, so the row stays busy until sign-in setup finishes.
    setBusyId(null);
    load();
  }

  async function removeRow(row) {
    if (
      !window.confirm(
        `Remove ${row.name} (${row.email})? They'll lose portal access immediately.`,
      )
    )
      return;
    setBusyId(row.id);
    const { error } = await supabase.from("staff").delete().eq("id", row.id);
    setBusyId(null);
    if (error) {
      // Profile photo history is kept (staff_photo_versions FK, no cascade).
      if (/staff_photo_versions/.test(error.message || "")) {
        showToast(
          `${row.name} has profile photos on file, which are kept. Switch them to Inactive instead.`,
        );
        return;
      }
      showToast(`Couldn't remove ${row.email}: ${error.message}`);
      return;
    }
    showToast(`Removed ${row.name}.`);
    load();
  }

  return (
    <div>
      <div className="mock-banner">
        <WarningIcon /> This page writes directly to the real staff table in
        Supabase — unlike the rest of the app, nothing here is sample data.
      </div>

      {readOnly && (
        <div className="mock-banner">
          <WarningIcon /> You have temporary read-only access to this page —
          contact an admin to make changes.
        </div>
      )}

      {!readOnly && missingAuth && missingAuth.length > 0 && (
        <div className="card staff-signin-card" style={{ marginBottom: 20 }}>
          <h3 className="card-title">
            Can't sign in yet{" "}
            <span className="staff-roster-count">({missingAuth.length})</span>
          </h3>
          <p className="card-subtitle">
            These active staff have no sign-in account, so Google will turn
            them away (new sign-ups are switched off). This happens when
            someone is added outside this page, or setup failed.
          </p>
          <ul className="staff-csv-preview">
            {missingAuth.map((m) => (
              <li key={m.email} className="negative">
                {m.name || m.email} ({m.email}) · {m.role}
              </li>
            ))}
          </ul>
          <div className="staff-reset-row">
            <button className="btn-primary" disabled={fixingAuth} onClick={fixSignIn}>
              {fixingAuth ? "Fixing…" : "Fix sign-in"}
            </button>
          </div>
        </div>
      )}

      {!readOnly && (
        <React.Fragment>
          <div className="card" style={{ marginBottom: 20 }}>
            <h3 className="card-title">Add staff</h3>
            <p className="card-subtitle">
              They'll sign in with Google using this exact address — add them
              here first, or Google will let them in and this app will turn them
              away.
            </p>
            <div className="staff-add-row">
              <input
                type="email"
                placeholder="name@mygoodbooks.org"
                value={newEmail}
                onChange={(e) => setNewEmail(e.target.value)}
              />
              <input
                type="text"
                placeholder="Full name"
                value={newName}
                onChange={(e) => setNewName(e.target.value)}
              />
              <select
                value={newRole}
                onChange={(e) => setNewRole(e.target.value)}
              >
                {STAFF_ROLES.map((r) => (
                  <option key={r} value={r}>
                    {r}
                  </option>
                ))}
              </select>
              <button
                className="btn-primary"
                disabled={adding || !newEmail.trim() || !newName.trim()}
                onClick={addStaff}
              >
                + Add
              </button>
            </div>
          </div>

          <div className="card" style={{ marginBottom: 20 }}>
            <h3 className="card-title">Bulk import</h3>
            <p className="card-subtitle">
              Paste rows as <code>email, name, role</code> (role optional,
              defaults to bookkeeper) — one person per line, straight out of a
              spreadsheet. A header row is fine, it's detected and skipped.
            </p>
            <textarea
              className="staff-csv-textarea"
              rows={4}
              placeholder={
                "jane@mygoodbooks.org, Jane Alvarez, bookkeeper\nmark@mygoodbooks.org, Mark Chen, admin"
              }
              value={csvText}
              onChange={(e) => {
                setCsvText(e.target.value);
                setCsvResults(null);
              }}
            />
            {csvPreview.length > 0 && (
              <React.Fragment>
                <ul className="staff-csv-preview">
                  {csvPreview.map((r, i) => (
                    <li
                      key={i}
                      className={r.errors.length ? "negative" : "positive"}
                    >
                      {r.errors.length ? (
                        <React.Fragment>
                          <strong>{r.line}</strong> — {r.errors.join(", ")}
                        </React.Fragment>
                      ) : (
                        <React.Fragment>
                          {r.name} ({r.email}) · {r.role}
                        </React.Fragment>
                      )}
                    </li>
                  ))}
                </ul>
                <div className="staff-reset-row">
                  <button
                    className="btn-primary"
                    disabled={csvImporting || csvValidCount === 0}
                    onClick={importCsv}
                  >
                    {csvImporting
                      ? "Importing…"
                      : `Import ${csvValidCount} staff`}
                  </button>
                  {csvValidCount < csvPreview.length && (
                    <p className="card-subtitle" style={{ margin: 0 }}>
                      {csvPreview.length - csvValidCount} row(s) above have
                      errors and will be skipped.
                    </p>
                  )}
                </div>
              </React.Fragment>
            )}
            {csvResults && (
              <ul className="staff-csv-preview" style={{ marginTop: 12 }}>
                {csvResults.map((r, i) => (
                  <li key={i} className={r.ok && !r.signInFailed ? "positive" : "negative"}>
                    {r.ok
                      ? r.signInFailed
                        ? staffAuthFailMessage("Added", r.name, r.signInFailed)
                        : `Added ${r.name}`
                      : `${r.name || r.email} — ${r.message}`}
                  </li>
                ))}
              </ul>
            )}
          </div>
        </React.Fragment>
      )}

      <div className="staff-roster-intro" style={{ marginBottom: 12 }}>
        <h3 className="card-title">Staff roster</h3>
        <p className="card-subtitle">
          Who can sign in to the portal, and with what role. You can't change
          your own row.
        </p>

        {rows === null && !loadError && (
          <p className="card-subtitle">Loading…</p>
        )}
        {loadError && <p className="card-subtitle negative">{loadError}</p>}
      </div>

      {canSeePhotos && canActPhotos && spList.rows && typeof SPA_BulkBar === "function" && (
        <SPA_BulkBar rows={spList.rows} canAct={canActPhotos} />
      )}
      {canSeePhotos && photoEmail && typeof SPA_PhotoDrawer === "function" && (
        <SPA_PhotoDrawer email={photoEmail} canAct={canActPhotos} onClose={() => setPhotoEmail(null)} />
      )}

      {rows && rows.length > 0 && [
        { key: "admin", title: "Admins", empty: "No admins yet." },
        { key: "bookkeeper", title: "Bookkeepers", empty: "No bookkeepers yet." },
      ].map((grp) => {
        // Display only: split by role, active first, then A-Z by name.
        const list = rows
          .filter((r) => (r.role === "admin" ? "admin" : "bookkeeper") === grp.key)
          .sort(
            (x, y) =>
              (x.active === false) - (y.active === false) ||
              String(x.name || x.email).localeCompare(String(y.name || y.email), undefined, { sensitivity: "base" }),
          );
        return (
      <div className="card staff-roster-card" key={grp.key} data-roster={grp.key} style={{ marginBottom: 20 }}>
        <h3 className="card-title">
          {grp.title} <span className="staff-roster-count">({list.length})</span>
        </h3>
        {list.length === 0 && <p className="card-subtitle">{grp.empty}</p>}
        {list.length > 0 && (
          <div className="table-scroll">
            <table className="tx-table tx-table-labeled">
              <thead>
                <tr>
                  <th>Name</th>
                  {canSeePhotos && <th>Photo</th>}
                  <th>Email</th>
                  <th>Birthday</th>
                  <th>Start date</th>
                  <th>Role</th>
                  <th>Active</th>
                  <th>Clients</th>
                  <th>Temp admin access</th>
                  {isInternalOwner && <th>MGB (internal)</th>}
                  <th></th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {list.map((row) => {
                  const isSelf = row.email === staffUser.email;
                  const busy = busyId === row.id;
                  const tempAccess = tempAccessMap[row.email];
                  const tempActive =
                    tempAccess &&
                    new Date(tempAccess.expires_at).getTime() > Date.now();
                  const tempBusy = tempAccessBusyId === row.id;
                  return (
                    <tr
                      key={row.id}
                      className={row.active === false ? "staff-roster-inactive" : undefined}
                      data-photo-row={String(row.email).toLowerCase()}
                    >
                      <td data-primary="">
                        {row.name}
                        {tempActive && row.role !== "admin" && (
                          <span className="staff-roster-temp" title="Has temporary admin access">Temp admin</span>
                        )}
                        {row.active && missingAuthSet.has(String(row.email).toLowerCase()) && (
                          <span
                            className="staff-roster-temp staff-roster-nosignin"
                            title="No sign-in account yet: use Fix sign-in at the top of this page"
                          >
                            Can't sign in
                          </span>
                        )}
                      </td>
                      {canSeePhotos && (
                        <td data-label="Photo">
                          <SPA_PhotoCell
                            row={spByEmail[String(row.email).toLowerCase()]}
                            profileName={row.name}
                            canAct={canActPhotos}
                            onOpen={setPhotoEmail}
                            tour={grp.key === (rows.some((r) => r.role === "admin") ? "admin" : "bookkeeper") && list[0] === row}
                          />
                        </td>
                      )}
                      <td data-label="Email">{row.email}</td>
                      <td data-label="Birthday">
                        {typeof ST_DateInput === "function" ? (
                          <ST_DateInput
                            value={(profiles[row.email] || {}).birthday}
                            max={new Date().toISOString().slice(0, 10)}
                            disabled={readOnly}
                            ariaLabel={`Birthday for ${row.name}`}
                            onSave={(v) => updateProfile(row, { birthday: v })}
                          />
                        ) : (
                          "—"
                        )}
                      </td>
                      <td data-label="Start date">
                        {typeof ST_DateInput === "function" ? (
                          <ST_DateInput
                            value={(profiles[row.email] || {}).start_date}
                            disabled={readOnly}
                            ariaLabel={`Start date for ${row.name}`}
                            onSave={(v) => updateProfile(row, { start_date: v })}
                          />
                        ) : (
                          "—"
                        )}
                      </td>
                      <td data-label="Role">
                        <select
                          value={row.role}
                          disabled={isSelf || busy || readOnly}
                          onChange={(e) =>
                            updateRow(row, { role: e.target.value })
                          }
                        >
                          {STAFF_ROLES.map((r) => (
                            <option key={r} value={r}>
                              {r}
                            </option>
                          ))}
                        </select>
                      </td>
                      <td data-label="Active">
                        <label className="staff-active-toggle">
                          <input
                            type="checkbox"
                            checked={row.active}
                            disabled={isSelf || busy || readOnly}
                            onChange={(e) =>
                              updateRow(row, { active: e.target.checked })
                            }
                          />
                          <span>{row.active ? "Active" : "Deactivated"}</span>
                        </label>
                      </td>
                      <td data-label="Clients">
                        {row.role === "admin" ? (
                          <span className="staff-self-note">All (admin)</span>
                        ) : (
                          <button
                            className="btn-secondary staff-clients-btn"
                            onClick={() => openClientAccess(row)}
                            disabled={readOnly}
                          >
                            Manage
                          </button>
                        )}
                        {/* Workload balancer (TeamCapacity.jsx), admins only. */}
                        {!readOnly && row.role !== "admin" && typeof TP_WorkloadHint === "function" && (
                          <TP_WorkloadHint email={row.email} />
                        )}
                      </td>
                      <td data-label="Temp admin access">
                        {readOnly ? (
                          tempActive ? (
                            <span className="staff-self-note">
                              Until{" "}
                              {formatTempAccessExpiry(tempAccess.expires_at)}
                            </span>
                          ) : (
                            <span className="staff-self-note">—</span>
                          )
                        ) : row.role === "admin" ? (
                          <span className="staff-self-note">—</span>
                        ) : (
                          <div className="staff-temp-access-cell" data-tour="members-temp">
                            {tempActive ? (
                              <React.Fragment>
                                <span className="staff-self-note">
                                  Until{" "}
                                  {formatTempAccessExpiry(
                                    tempAccess.expires_at,
                                  )}
                                </span>
                                <button
                                  className="btn-secondary"
                                  disabled={tempBusy}
                                  onClick={() => revokeTempAccess(row)}
                                >
                                  Revoke
                                </button>
                              </React.Fragment>
                            ) : (
                              <React.Fragment>
                                <select
                                  value={
                                    tempAccessDurationFor[row.id] ||
                                    TEMP_ACCESS_DURATIONS[0].ms
                                  }
                                  onChange={(e) =>
                                    setTempAccessDurationFor((prev) => ({
                                      ...prev,
                                      [row.id]: Number(e.target.value),
                                    }))
                                  }
                                >
                                  {TEMP_ACCESS_DURATIONS.map((d) => (
                                    <option key={d.label} value={d.ms}>
                                      {d.label}
                                    </option>
                                  ))}
                                </select>
                                <button
                                  className="btn-secondary"
                                  disabled={tempBusy}
                                  onClick={() => grantTempAccess(row)}
                                >
                                  Grant
                                </button>
                              </React.Fragment>
                            )}
                          </div>
                        )}
                      </td>
                      {isInternalOwner && (
                        <td data-label="MGB (internal)">
                          {row.role !== "admin" ? (
                            <span className="staff-self-note">—</span>
                          ) : (internalGrants[String(row.email).toLowerCase()] || {}).is_owner ? (
                            <span className="staff-self-note">Owner</span>
                          ) : (
                            <label className="staff-active-toggle" data-tour="members-internal">
                              <input
                                type="checkbox"
                                checked={!!internalGrants[String(row.email).toLowerCase()]}
                                disabled={internalBusyId === row.id || !row.active}
                                aria-label={`Let ${row.name} open MGB (internal)`}
                                onChange={(e) => toggleInternalAccess(row, e.target.checked)}
                              />
                              <span>
                                {internalGrants[String(row.email).toLowerCase()] ? "Can open" : "No access"}
                              </span>
                            </label>
                          )}
                        </td>
                      )}
                      <td data-label="">
                        <div className="staff-row-actions">
                        {!isSelf && row.role !== "admin" && row.active && (
                          <button
                            className="btn-secondary staff-view-as-btn"
                            onClick={() => onImpersonate(row)}
                            disabled={readOnly}
                          >
                            View as
                          </button>
                        )}
                        {/* Last seen: admins only (readOnly covers temporary admins); also
                            for admin and inactive rows, outside the View as condition. */}
                        {!isSelf && !readOnly && <SA_LastSeenButton row={row} />}
                        {!isSelf && !readOnly && row.active && typeof OFF_OffboardButton === "function" && (
                          <OFF_OffboardButton row={row} staffRows={rows} onDone={load} disabled={busy} />
                        )}
                        </div>
                      </td>
                      <td className="row-remove-cell">
                        {isSelf ? (
                          <span className="staff-self-note">You</span>
                        ) : (
                          <button
                            className="row-remove-btn"
                            onClick={() => removeRow(row)}
                            disabled={busy || readOnly}
                            aria-label={`Remove ${row.name}`}
                          >
                            ×
                          </button>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}

              </div>
        );
      })}

      {rows && rows.length === 0 && !loadError && (
        <div className="card" style={{ marginBottom: 20 }}>
          <p className="card-subtitle">No staff rows yet.</p>
        </div>
      )}

      {clientAccessFor && (
        <ModalShell
          onClose={() => setClientAccessFor(null)}
          labelledBy="client-access-title"
        >
          <div className="modal-header">
            <h3
              className="card-title"
              id="client-access-title"
              style={{ margin: 0 }}
            >
              {clientAccessFor.name}'s clients
            </h3>
            <button
              className="modal-close"
              onClick={() => setClientAccessFor(null)}
              aria-label="Close"
            >
              ×
            </button>
          </div>
          <p className="card-subtitle">
            Unchecked means they can't see this client at all — not just a
            restricted view, the client won't appear in their switcher.
          </p>
          {!readOnly && typeof TP_WorkloadHint === "function" && (
            <p className="card-subtitle">
              Workload:
              <TP_WorkloadHint
                email={clientAccessFor.email}
                clientCount={clientAccessLoading ? undefined : clientAccessSet.size}
              />
            </p>
          )}
          <div className="modal-body">
            {clientAccessLoading && <p className="card-subtitle">Loading…</p>}
            {!clientAccessLoading &&
              CF_sort(
                CLIENTS.filter(
                  (c) => !c.isInternal && (c.testOnly !== true || cfShowTest || clientAccessSet.has(c.id)),
                ),
              ).map((c) => (
                <label className="tab-toggle-row" key={c.id}>
                  <input
                    type="checkbox"
                    checked={clientAccessSet.has(c.id)}
                    onChange={() => toggleClientAccess(c.id)}
                  />
                  <span>
                    {c.name}
                    <CF_Badge client={c} />
                  </span>
                </label>
              ))}
          </div>
          <div className="modal-footer">
            <button
              className="btn-primary"
              onClick={() => setClientAccessFor(null)}
            >
              Done
            </button>
          </div>
        </ModalShell>
      )}
    </div>
  );
}

// Parses pasted CSV for bulk client-contact import: client_id,email,name,role
// per line. Same tiny/no-quoted-fields approach as parseStaffCsv, plus a
// client_id column checked against the real CLIENTS list instead of a fixed
// role enum. client_id has to be the exact slug (e.g. "grace-community"),
// not the display name — there's no fuzzy matching here.
function parseClientUserCsv(text) {
  const lines = text
    .split(/\r?\n/)
    .map((l) => l.trim())
    .filter(Boolean);
  const rows = [];
  lines.forEach((line, i) => {
    const [rawClientId, rawEmail, rawName, rawRole] = line
      .split(",")
      .map((f) => (f || "").trim());
    if (i === 0 && rawEmail && !rawEmail.includes("@")) return; // header row
    const clientId = rawClientId || "";
    const email = (rawEmail || "").toLowerCase();
    const name = rawName || "";
    const role = rawRole || "";
    const errors = [];
    const client = CLIENTS.find((c) => c.id === clientId);
    if (!clientId || !client) errors.push("unknown client id");
    if (!email || !email.includes("@")) errors.push("missing/invalid email");
    if (!name) errors.push("missing name");
    if (!role) errors.push("missing role");
    rows.push({
      line,
      clientId,
      clientName: client ? client.name : clientId,
      email,
      name,
      role,
      errors,
    });
  });
  return rows;
}

// ----------------------------------------------------------------------------
// Developer Tools (admin only) — per-browser QA toggles and local-state
// reset. Split out of Staff Access into its own sidebar page: it has nothing
// to do with who can sign in, and burying browser-only debugging aids in
// the middle of a page that writes to the real staff table made them easy
// to overlook and easy to confuse for something that affects other staff.
// ----------------------------------------------------------------------------

function readAllMygoodbooksStorage() {
  try {
    return Object.keys(localStorage)
      .filter((k) => k.startsWith("mygoodbooks_") || k.startsWith("mgb-") || k.startsWith("mgb_"))
      .sort()
      .map((key) => ({ key, value: localStorage.getItem(key) }));
  } catch (e) {
    return [];
  }
}

// Pretty-prints a stored value if it's JSON, otherwise shows it as-is — most
// keys here are JSON (layouts, tab config, ...), a few are plain strings
// (theme, page) or bare numbers (a cash-floor threshold).
function formatStorageValue(raw) {
  try {
    return JSON.stringify(JSON.parse(raw), null, 2);
  } catch (e) {
    return raw;
  }
}

// The old "Jump to client" card here was removed — the staff top bar's client
// picker (components/staff/TopBar.jsx) does that job on every page now.
// "*/15 * * * *" → "every 15 min", "0 13 * * 1-5" → "weekdays 13:00 UTC".
// Anything fancier shows as the raw cron expression.
function cronScheduleLabel(expr) {
  if (!expr) return "";
  const m = String(expr).trim().split(/\s+/);
  if (m.length !== 5) return expr;
  const [min, hour, dom, mon, dow] = m;
  const pad = (n) => String(n).padStart(2, "0");
  const DAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
  if (min === "*" && hour === "*") return "every minute";
  if (/^\*\/\d+$/.test(min) && hour === "*" && dom === "*" && mon === "*" && dow === "*")
    return `every ${min.slice(2)} min`;
  if (/^\d+$/.test(min) && /^\*\/\d+$/.test(hour) && dom === "*" && dow === "*")
    return `every ${hour.slice(2)} h at :${pad(min)}`;
  if (/^\d+$/.test(min) && /^\d+$/.test(hour) && dom === "*" && mon === "*") {
    const t = `${pad(hour)}:${pad(min)} UTC`;
    if (dow === "*") return `daily ${t}`;
    if (dow === "1-5") return `weekdays ${t}`;
    const days = dow
      .split(",")
      .map((d) => DAYS[Number(d)] || d)
      .join(", ");
    return `${days} ${t}`;
  }
  if (/^\d+$/.test(min) && /^\d+$/.test(hour) && /^\d+$/.test(dom) && mon === "*")
    return `day ${dom} of the month, ${pad(hour)}:${pad(min)} UTC`;
  return expr;
}

function DeveloperToolsPage({ staffUser, readOnly }) {
  const supabase = window.mgbSupabase;
  const [, forceRerender] = useState(0);
  const [storageEntries, setStorageEntries] = useState(
    readAllMygoodbooksStorage,
  );
  const [auditRows, setAuditRows] = useState(null);
  const [auditError, setAuditError] = useState("");
  // Only a read-status check, not the roster itself — Staff Access owns the
  // actual roster fetch/CRUD; this just needs to know whether a read against
  // the staff table succeeds, for the System Info card below.
  const [staffReadOk, setStaffReadOk] = useState(null); // null = checking, else boolean
  const [staffReadError, setStaffReadError] = useState("");
  const showToast = useToast();
  // Live cards (supabase/usage-stats-2.sql): every pg_cron job with its last
  // run, errors the app reported from people's browsers, and a test email
  // through the dev-tools function.
  const [jobs, setJobs] = useState(null); // null = loading
  const [jobsError, setJobsError] = useState("");
  const [runningJob, setRunningJob] = useState("");
  const [clientErrors, setClientErrors] = useState(null); // null = loading
  const [clientErrorsError, setClientErrorsError] = useState("");
  const [openErrorId, setOpenErrorId] = useState(null);
  const [testEmail, setTestEmail] = useState({ busy: false, ok: null, text: "" });
  // Tasks switches (tk_settings, read-only here): the owner flips
  // standard_set_live on Tasks › Recurring.
  const [tkSettings, setTkSettings] = useState(null); // null = loading
  const [tkSettingsError, setTkSettingsError] = useState("");
  // P4-2: how many clients get month-end tasks from the Close checklist
  // (tk_client_close_optin, set per client on Tasks › Recurring › One client).
  const [closeOptinCount, setCloseOptinCount] = useState(null); // null = loading or missing
  useEffect(() => {
    if (!supabase) return;
    supabase
      .from("tk_client_close_optin")
      .select("client_id", { count: "exact", head: true })
      .is("disabled_at", null)
      .then(({ count, error }) => setCloseOptinCount(error ? null : count || 0));
  }, [supabase]);

  useEffect(() => {
    if (!supabase) return;
    supabase
      .from("tk_settings")
      .select("key, value, updated_by, updated_at")
      .then(({ data, error }) => {
        if (error) {
          setTkSettingsError("Couldn't load Slate switches. " + error.message);
          setTkSettings({});
          return;
        }
        const out = {};
        (data || []).forEach((r) => {
          out[r.key] = r;
        });
        // Ask client's owner-only live switch sits on client_email_settings
        // (tasks p2 s5); shown here read-only next to the tk_settings rows.
        supabase
          .from("client_email_settings")
          .select("client_request_enabled, updated_at")
          .eq("id", true)
          .maybeSingle()
          .then((res) => {
            if (res && !res.error && res.data) {
              out.__client_request_enabled = { key: "client_request_enabled", value: !!res.data.client_request_enabled, updated_at: null };
            }
            setTkSettingsError("");
            setTkSettings(Object.assign({}, out));
          });
      });
  }, [supabase]);

  const loadJobs = useCallback(() => {
    if (!supabase) return;
    supabase.rpc("cron_health").then(({ data, error }) => {
      if (error) {
        setJobsError("Couldn't load scheduled jobs. " + error.message);
        setJobs([]);
      } else {
        setJobsError("");
        setJobs(Array.isArray(data) ? data : []);
      }
    });
  }, [supabase]);

  useEffect(() => {
    loadJobs();
  }, [loadJobs]);

  const loadClientErrors = useCallback(() => {
    if (!supabase) return;
    supabase
      .from("client_errors")
      .select("id, created_at, actor_email, actor_role, page, message, stack, source, app_version, device")
      .order("created_at", { ascending: false })
      .limit(30)
      .then(({ data, error }) => {
        if (error) {
          setClientErrorsError("Couldn't load errors. " + error.message);
          setClientErrors([]);
        } else {
          setClientErrorsError("");
          setClientErrors(data || []);
        }
      });
  }, [supabase]);

  useEffect(() => {
    loadClientErrors();
  }, [loadClientErrors]);

  function runJob(name) {
    if (!supabase || runningJob) return;
    if (
      !window.confirm(
        `Run "${name}" now? It does exactly what the schedule does at its next tick (emails included).`,
      )
    )
      return;
    setRunningJob(name);
    supabase.rpc("cron_run_now", { p_jobname: name }).then(({ error }) => {
      if (error) showToast("Couldn't start " + name + ": " + error.message);
      else showToast("Started " + name + ". Its result shows here once it finishes.");
      setTimeout(() => {
        setRunningJob("");
        loadJobs();
      }, 4000);
    });
  }

  function sendTestEmail() {
    if (!supabase || testEmail.busy) return;
    setTestEmail({ busy: true, ok: null, text: "Sending…" });
    supabase.functions
      .invoke("dev-tools", { body: { action: "test-email" } })
      .then(({ data, error }) => {
        if (error || !data || data.ok === false) {
          const msg = (data && data.error) || (error && error.message) || "Unknown error";
          setTestEmail({ busy: false, ok: false, text: "Not sent: " + msg });
        } else {
          setTestEmail({ busy: false, ok: true, text: `Sent to ${data.to}. Check your inbox (and spam).` });
        }
      })
      .catch((e) => setTestEmail({ busy: false, ok: false, text: "Not sent: " + (e && e.message) }));
  }

  const loadAudit = useCallback(() => {
    if (!supabase) return;
    supabase
      .from("staff_audit_log")
      .select("id, actor_email, action, target_email, detail, created_at")
      .order("created_at", { ascending: false })
      .limit(20)
      .then(({ data, error }) => {
        if (error) {
          setAuditError("Couldn't load recent activity. " + error.message);
          setAuditRows([]);
        } else {
          setAuditError("");
          setAuditRows(data);
        }
      });
  }, [supabase]);

  useEffect(() => {
    loadAudit();
  }, [loadAudit]);

  useEffect(() => {
    if (!supabase) {
      setStaffReadOk(false);
      setStaffReadError("Supabase isn't configured — see auth-config.js.");
      return;
    }
    supabase
      .from("staff")
      .select("id")
      .limit(1)
      .then(({ error }) => {
        setStaffReadOk(!error);
        setStaffReadError(error ? error.message : "");
      });
  }, [supabase]);

  function toggleFlag(key) {
    setFlag(key, !isFlagOn(key));
    forceRerender((v) => v + 1);
    const spec = FEATURE_FLAGS.find((f) => f.key === key);
    if (spec && spec.reloads) setTimeout(() => window.location.reload(), 150);
  }

  function resetLocalState() {
    if (
      !window.confirm(
        "Reset this browser's local MyGoodBooks state (theme, tab layout, dashboard/Financial Overview widget layouts, cash-floor alerts, per-person access overrides, the tour and first sign-in prompts, dismissed page hints, recent clients, the tab last open on each client, Tasks views, folded groups, Follow my client and whether you have seen an Unassigned task, ...)? This only affects this browser — nothing in Supabase is touched. The page will reload.",
      )
    ) {
      return;
    }
    resettableLocalStorageKeys().forEach((key) => {
      try {
        localStorage.removeItem(key);
      } catch (e) {}
    });
    // Per-tab memory in sessionStorage: the client portal's last-used Finances
    // tab (CLIENT_rememberTab), the staff last-open tab per client
    // (STAFF_lastTabKey), a deep link waiting to land (LK_KEY), and the
    // Onboarding card's open state per client (OB_openKey).
    try {
      Object.keys(sessionStorage)
        .filter(
          (k) =>
            k.startsWith("mgb_client_tab_") ||
            k.startsWith("mgb_staff_client_tab_") ||
            k === "mgb_lk_arrival_v1" ||
            k.startsWith("mgb_ov_onboarding_open_"),
        )
        .forEach((k) => sessionStorage.removeItem(k));
    } catch (e) {}
    window.location.reload();
  }

  return (
    <div>
      <MockBanner text="Feature flags and local storage are per-browser testing aids. Scheduled jobs, errors and the test email are live: Run now does the real thing." />

      {readOnly && (
        <div className="mock-banner">
          <WarningIcon /> You have temporary read-only access to this page —
          contact an admin to make changes. (These controls are only local to
          your own browser anyway, but they stay disabled to match Staff Access
          and Client Roster.)
        </div>
      )}

      <div className="card" style={{ marginBottom: 20 }}>
        <h3 className="card-title">Slate switches</h3>
        <p className="card-subtitle">
          Firm-wide, from tk_settings (and the Ask client switch from client_email_settings). Read-only here: the owner flips the standard close set on Slate › Recurring and Ask client emails live on Settings › Firm settings › Emails (Client emails card); admins set the month rhythm on Settings › Firm settings › Month rhythm.
        </p>
        {tkSettingsError ? <p className="card-subtitle">{tkSettingsError}</p> : null}
        {tkSettings === null ? (
          <p className="card-subtitle">Loading…</p>
        ) : (
          [
            ["standard_set_live", "Standard close set live for real clients", "Off (or missing) means the set only reaches test clients."],
            ["__client_request_enabled", "Ask client emails live", "Owner-only. The owner flips it on Settings › Firm settings › Emails, Client emails card, row Ask client emails live (client_email_settings.client_request_enabled; turning on asks to confirm who gets emailed; every change is in tk_settings_audit). Off means every Ask client email and reminder to a real client is a dry run; nothing is sent. On sends only to real clients in the pilot list below. Test clients always get one [Test] copy to the sender only (needs Send client emails on). Sent by the tk-client-requests edge function; reminders by client-emails (cron client-request-nudge)."],
            ["client_request_pilot", "Ask client pilot clients", "Which real clients get Ask client emails once the switch above is on (\"all\" or a list of client ids). Not set means none. Owner-only; shown on the Emails page next to the switch."],
            ["nudge_max", "Ask client reminders before No reply", "Reminders sent before a request shows No reply."],
            ["token_ttl_days", "Answer link lifetime (days)", "How long an Ask client answer link works."],
            ["on_time_since", "On-time counted since", "Start date for on-time stats and the missed-periods floor."],
            ["late_tasks_count_against_staff", "Late tasks count in scores and reports", "Owner-only. Off (the default, a grace period while everyone settles into Slate): late and overdue tasks are left out of the performance score (other inputs re-weighted), client health, on-time stats, the weekly digest and the Team page's Overdue columns. Filing deadlines are not tasks and still count. The owner flips it on Settings › Firm settings › Late tasks (tk_set_late_tasks_count; turning it on stamps the date below). Each change is audited."],
            ["late_tasks_effective_from", "Late tasks counted from", "Set when the owner turns the switch on: only tasks due on or after this date count, so the imported backlog is never held against anyone. Not set while the switch has never been on."],
            ["ooo_auto_apply", "Time off hands tasks to backups", "Off (false or not set, the default): only the manual Hand my tasks to backups button moves tasks. Set to true and the tk-ooo-daily cron (11:00 UTC) also moves open tasks due during someone's time off to each client's backup on their first day off (never re-taking a task someone handed back). Handing back after the time off always runs."],
            ["asana_import_apply_enabled", "Asana import apply", "Off (or missing) blocks tk_import_asana_apply. The one-time import ran 2026-10-16. From 2026-10-25 to 2026-11-24 the daily Asana import (scripts/asana-import/dailyImport.js, runbook docs/asana-daily-import.md) turns it on only inside its own apply transaction and off again in the same transaction, so it reads Off here between runs; if a run finds it already on, the run stops without touching it. Never turn it on by hand while the daily runs continue. Undo works with it off."],
            ["wb_enabled", "Desk and new Today on for staff", "Off (or missing, the default) keeps Today and the nav as they were for everyone. Owner turns it on (true) to give every staff member the Needs you list on Today and the Desk (press D). Each person can still opt out with Classic Today in Feature flags. If it is ever turned off again, it is off for everyone (there is no personal preview any more)."],
            ["threadmenu_enabled", "Message thread menu for all staff (owner only)", "Off = only people with the Thread menu preview flag see it. Off (or missing, the default) keeps Messages and the Desk Inbox exactly as they are: no right-click menu or ⋯ on threads, no Done, Snoozed or Hidden chips, no thread tags. Owner turns it on (true) from the SQL editor (override first; see the README Thread menu launch checklist), never from here. Never shown to clients; off in View as."],
            ["deskplus_enabled", "Desk additions for staff", "Owner-only; off = hidden. Off (or missing, the default) keeps the Desk exactly as it is for everyone: no Ledger chip in the Inbox, no Waiting on client, recent messages or recent files on the Client tab, no Ask client or Message buttons there, and no Ask client…, Message… or Time off in the + menu. Owner turns it on (true) from the SQL editor (override first; see the README Desk additions launch checklist), never from here, to give those to every staff member who has the Desk. Each person can try it early with Desk additions preview in Feature flags. Needs the Desk on (wb_enabled, unless the person picked Classic Today)."],
            ["org_profile_enabled", "Client org profile + gifts", "On since 2026-10-25: clients get the profile prompt, staff the Organization profile card and onboarding step, real admins Team › Client gifts, and the weekly digest the anniversaries line, plus the launch notice and tour. Owner-only; off would hide it again. Off (or missing) hides everything in the client org profile build: no client prompt, Needs-you item or ? menu entry, no Organization profile card on a client's Overview, no Team › Client gifts tab, no onboarding step and no digest line. Owner turns it on (true) with one SQL line, never from here. Each person can try it early with Client org profile + gifts (preview) in Feature flags. Nothing emails clients and nothing orders gifts either way."],
            ["org_gift_basis", "Client gifts: anniversary to follow", "Which anniversary Team › Client gifts and the weekly digest follow, for the whole firm: client_since (Client since, the default; not set means this) or established (the founding date, with Client since for clients whose founding date is Not sure or blank). Admins change it on Team › Client gifts › Anniversary to follow (every change audited; the database refuses any other value)."],
            ["slate_app_enabled", "Slate app on for staff", "On since 2026-10-25 (launched for Monday 2026-10-26): every staff member gets the Slate app (own page at /slate, a detail pane on wide windows, a sliver for the current task, Open Slate app), plus the launch notice and tour. Owner-only, set with one SQL line, never from here; read-only here. Each person can opt out with Classic tasks page in Feature flags. Off (or missing) would put Slate back the way it was for everyone (Open in own window opens the old small window) right away."],
            ["nav_enabled", "Left sidebar for staff", "Off (or missing, the default) keeps the staff rail as it was for everyone. Owner turns it on (true) with one SQL line, never from here, to give every staff member Pinned and Recent clients and a Customize gear in the left sidebar, plus the Alerts section for real admins. If it is ever turned off again, it is off for everyone (there is no personal preview any more). Setting it to true turns the sidebar on for every staff member right away, so do it only at launch."],
            ["lato_enabled", "Lato font for everyone", "Off (or missing, the default) keeps Bitter headings and IBM Plex Sans body text for everyone. Owner turns it on (true) with one SQL line, never from here, to switch the whole app to Lato (numbers keep their monospace font). Each person can opt out with Classic fonts in Feature flags. If it is ever turned off again, it is off for everyone (there is no personal preview any more). Setting it to true changes the look for every staff member right away, so do it only at launch."],
            ["brand_enabled", "Brand colors for everyone", "Off (or missing, the default) keeps the current colors and headings for everyone. Owner turns it on (true) with one SQL line, never from here, to switch the whole app to the brand guide's navy and dark teal with Montserrat headings. Each person can opt out with Classic colors in Feature flags. If it is ever turned off again, it is off for everyone (there is no personal preview any more). Setting it to true changes the look for every staff member right away, so do it only at launch."],
            ["hovernav_enabled", "Hover menus for everyone", "Off (or missing, the default) keeps the sidebars as they are for everyone. Owner turns it on (true) with one SQL line, never from here, to open a small menu of tabs when you point at a sidebar icon (Work, Team, HR, Finances) and to replace the gray browser tooltips with themed ones. Each person can opt out with Classic menus in Feature flags. If it is ever turned off again, it is off for everyone (there is no personal preview any more). Setting it to true changes the sidebars for every staff member right away, so do it only at launch."],
            ["layout_defaults", "Sidebar defaults by role", "What each role (admin, account manager, bookkeeper, temp admin) sees in the left sidebar until they customize it. Admins edit it in Settings › Firm settings › Sidebar defaults (shown once the sidebar is on). Not set means the built-in layout."],
            ["month_rhythm", "Month rhythm (Slate)", "The three days each month when Slate's monthly tasks come due: Check in, Send reports, Follow up, and what happens on a weekend or firm holiday. Admins edit it on Settings › Firm settings › Month rhythm (every change audited; the database refuses an invalid value). Not set means 4th, 14th, 24th, next business day. A client can have its own three days (client Settings tab, admins only); labels and the weekend rule stay firm-wide."],
            ["month_rhythm_enabled", "Month rhythm tasks on for everyone", "On since 2026-10-25 (the owner turned it on for the Monday 2026-10-26 launch; index.html caches it as mgb_rhythm_cache). Off (or missing): the daily task run makes nothing from the eight MGB Month Rhythm templates for real clients (test and internal clients still get them from Make due tasks now), the month-rhythm-daily job sends no emails, and Slate › Recurring hides them unless you have Month rhythm preview on. Turning it on stamps the set's live_since, so only dates from that day on are made. Owner-only; set with one SQL line, never from here. Each person can try the work early with Month rhythm preview in Feature flags."],
            ["wb_gl_due_bday", "Desk Ledger flags due (business day)", "Business day of the month after a period when open Ledger flags count as due on the Desk. Not set means 10."],
            ["wb_doc_check_from", "Desk new files from", "Client uploads before this date never show as new files on the Desk. Not set means 2026-10-16."],
            ["__close_optin_count", "Clients with month-end tasks from the Close checklist (visible to you)", "How many clients you can see are turned on (tk_client_close_optin, disabled_at empty). Set per client by an admin or that client's account manager on Slate › Recurring › One client; off by default. Works while the standard close set is off."],
          ].map(([key, label, desc]) => {
            const row = key === "__close_optin_count" ? (closeOptinCount === null ? null : { value: closeOptinCount }) : tkSettings[key];
            const raw = row ? row.value : undefined;
            const val = raw === undefined || raw === null ? "Not set" : raw === true ? "On" : raw === false ? "Off"
              : key === "month_rhythm" && typeof TK_rhythmSummary === "function" ? TK_rhythmSummary(raw) : String(raw);
            return (
              <div className="staff-flag-row" key={key}>
                <span className={"pill " + (raw === true ? "good" : "neutral")} style={{ flexShrink: 0 }}>{val}</span>
                <span>
                  <span className="staff-flag-label">{label}</span>
                  <span className="staff-flag-desc">
                    {desc} <code>{key.replace(/^__/, "")}</code>
                    {row && row.updated_at ? " · changed " + String(row.updated_at).slice(0, 10) : ""}
                  </span>
                </span>
              </div>
            );
          })
        )}
      </div>

      <fieldset
        disabled={readOnly}
        style={{ border: 0, margin: 0, padding: 0 }}
      >
        <div className="card" style={{ marginBottom: 20 }}>
          <h3 className="card-title">Feature flags</h3>
          <p className="card-subtitle">
            Stored in this browser's localStorage only.
          </p>

          {FEATURE_FLAGS.map((f) => (
            <label className="staff-flag-row" key={f.key}>
              <input
                type="checkbox"
                checked={isFlagOn(f.key)}
                onChange={() => toggleFlag(f.key)}
              />
              <span>
                <span className="staff-flag-label">{f.label}</span>
                <span className="staff-flag-desc">{f.description}</span>
              </span>
            </label>
          ))}

          <div className="staff-reset-row">
            <button className="btn-secondary" onClick={resetLocalState}>
              Reset local state
            </button>
            <p className="card-subtitle" style={{ margin: 0 }}>
              Clears every saved theme, tab layout, widget layout, the "Show
              test clients" switch, and per-person access override under this
              browser's "mygoodbooks_" / "mgb-" storage (feature flags excepted — those stay, right above), then
              reloads. Doesn't touch Supabase or any other browser.
            </p>
          </div>
        </div>

        <div className="card">
          <div className="page-header" style={{ marginBottom: 4 }}>
            <div>
              <h3 className="card-title">Raw local storage</h3>
              <p className="card-subtitle" style={{ margin: 0 }}>
                Every "mygoodbooks_" key in this browser, as actually stored —
                for when a bug report says "my layout looks wrong" and you want
                the real value without opening devtools.
              </p>
            </div>
            <button
              className="btn-secondary"
              onClick={() => setStorageEntries(readAllMygoodbooksStorage())}
            >
              Refresh
            </button>
          </div>
          {storageEntries.length === 0 ? (
            <p className="card-subtitle">
              No "mygoodbooks_" keys stored in this browser.
            </p>
          ) : (
            <div className="staff-audit-list">
              {storageEntries.map((e) => (
                <div
                  className="staff-audit-row"
                  key={e.key}
                  style={{ flexDirection: "column", alignItems: "stretch" }}
                >
                  <span className="staff-flag-label">{e.key}</span>
                  <pre
                    style={{
                      margin: "4px 0 0",
                      fontSize: 11.5,
                      fontFamily: "IBM Plex Mono, monospace",
                      color: "var(--text-muted)",
                      whiteSpace: "pre-wrap",
                      wordBreak: "break-word",
                    }}
                  >
                    {formatStorageValue(e.value)}
                  </pre>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="card" style={{ marginTop: 20, marginBottom: 20 }}>
          <h3 className="card-title">Recent activity</h3>
          <p className="card-subtitle">
            Every change to the staff table, logged automatically by Postgres —
            not just the ones made from Staff Access.
          </p>

          {auditRows === null && !auditError && (
            <p className="card-subtitle">Loading…</p>
          )}
          {auditError && <p className="card-subtitle negative">{auditError}</p>}

          {auditRows && auditRows.length > 0 && (
            <ul className="staff-audit-list">
              {auditRows.map((entry) => (
                <li className="staff-audit-row" key={entry.id}>
                  <span className="staff-audit-text">
                    <strong>{entry.actor_email || "Unknown"}</strong>{" "}
                    {staffAuditVerb(entry.action)}{" "}
                    <strong>{entry.target_email}</strong>
                    {entry.detail ? ` (${entry.detail})` : ""}
                  </span>
                  <span className="staff-audit-time">
                    {fmtDateTime(entry.created_at)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          {auditRows && auditRows.length === 0 && !auditError && (
            <p className="card-subtitle">No activity recorded yet.</p>
          )}
        </div>

        <div className="card" style={{ marginBottom: 20 }}>
          <div className="page-header" style={{ marginBottom: 4 }}>
            <div>
              <h3 className="card-title">Scheduled jobs</h3>
              <p className="card-subtitle" style={{ margin: 0 }}>
                Every automatic job in the database (email outbox, digest,
                QuickBooks sync, health checks, chasers) with its last run.
                <strong> Run now</strong> starts one straight away; the HTTP
                jobs return as soon as the function is called, so check back
                in a minute for the result.
              </p>
            </div>
            <button className="btn-secondary" onClick={loadJobs}>
              Refresh
            </button>
          </div>
          {jobs === null && !jobsError && (
            <p className="card-subtitle">Loading…</p>
          )}
          {jobsError && <p className="card-subtitle negative">{jobsError}</p>}
          {jobs && jobs.length === 0 && !jobsError && (
            <p className="card-subtitle">No scheduled jobs found.</p>
          )}
          {jobs && jobs.length > 0 && (
            <div className="dt-table-wrap">
              <table className="dt-table">
                <thead>
                  <tr>
                    <th>Job</th>
                    <th>Schedule</th>
                    <th>Last run</th>
                    <th>Result</th>
                    <th></th>
                  </tr>
                </thead>
                <tbody>
                  {jobs.map((j) => (
                    <tr key={j.jobid}>
                      <td>
                        <span className="staff-flag-label">{j.jobname}</span>
                        {!j.active && (
                          <span className="pill neutral" style={{ marginLeft: 6 }}>
                            paused
                          </span>
                        )}
                      </td>
                      <td>
                        <span title={j.schedule}>{cronScheduleLabel(j.schedule)}</span>
                      </td>
                      <td style={{ whiteSpace: "nowrap" }}>
                        {j.last_start ? fmtDateTime(j.last_start) : "never"}
                      </td>
                      <td>
                        {j.last_status ? (
                          <span
                            className={
                              "pill " +
                              (j.last_status === "succeeded"
                                ? "good"
                                : j.last_status === "failed"
                                  ? "bad"
                                  : "neutral")
                            }
                          >
                            {j.last_status}
                          </span>
                        ) : (
                          <span className="pill neutral">no runs yet</span>
                        )}
                        {j.failed_7d > 0 && (
                          <span className="card-subtitle" style={{ margin: "0 0 0 8px" }}>
                            {j.failed_7d} failed in 7 days
                          </span>
                        )}
                        {j.last_status === "failed" && j.last_message && (
                          <div
                            className="card-subtitle"
                            style={{ margin: "4px 0 0", wordBreak: "break-word" }}
                          >
                            {j.last_message}
                          </div>
                        )}
                      </td>
                      <td style={{ textAlign: "right" }}>
                        <button
                          className="btn-secondary"
                          disabled={!!runningJob}
                          onClick={() => runJob(j.jobname)}
                        >
                          {runningJob === j.jobname ? "Starting…" : "Run now"}
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        <div className="card" style={{ marginBottom: 20 }}>
          <div className="page-header" style={{ marginBottom: 4 }}>
            <div>
              <h3 className="card-title">Recent errors</h3>
              <p className="card-subtitle" style={{ margin: 0 }}>
                Errors the app caught in someone's browser, newest first (last
                30). Click one for the technical detail to pass on to whoever
                is fixing it.
              </p>
            </div>
            <button className="btn-secondary" onClick={loadClientErrors}>
              Refresh
            </button>
          </div>
          {clientErrors === null && !clientErrorsError && (
            <p className="card-subtitle">Loading…</p>
          )}
          {clientErrorsError && (
            <p className="card-subtitle negative">{clientErrorsError}</p>
          )}
          {clientErrors && clientErrors.length === 0 && !clientErrorsError && (
            <p className="card-subtitle">No errors reported. Good.</p>
          )}
          {clientErrors && clientErrors.length > 0 && (
            <div className="dt-table-wrap">
              <table className="dt-table">
                <thead>
                  <tr>
                    <th>When</th>
                    <th>Who</th>
                    <th>Page</th>
                    <th>Version</th>
                    <th>Error</th>
                  </tr>
                </thead>
                <tbody>
                  {clientErrors.map((e) => (
                    <tr
                      key={e.id}
                      className="dt-error-row"
                      onClick={() => setOpenErrorId(openErrorId === e.id ? null : e.id)}
                    >
                      <td style={{ whiteSpace: "nowrap" }}>{fmtDateTime(e.created_at)}</td>
                      <td>
                        {e.actor_email || "—"}
                        {e.actor_role ? (
                          <span className="card-subtitle" style={{ margin: 0 }}>
                            {" "}
                            · {e.actor_role}
                          </span>
                        ) : null}
                      </td>
                      <td>
                        {e.page || "—"}
                        {e.device ? (
                          <span className="card-subtitle" style={{ margin: 0 }}>
                            {" "}
                            · {e.device}
                          </span>
                        ) : null}
                      </td>
                      <td>{e.app_version || "—"}</td>
                      <td style={{ wordBreak: "break-word" }}>
                        {e.message}
                        {openErrorId === e.id && (
                          <pre className="dt-stack">
                            {[e.source, e.stack].filter(Boolean).join("\n") ||
                              "No further detail."}
                          </pre>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        <div className="content-masonry">
          <div className="card">
            <h3 className="card-title">System info</h3>
            <p className="card-subtitle">
              What the app is actually talking to, for debugging a broken login
              or a stale deploy.
            </p>
            <dl className="staff-info-list">
              <div>
                <dt>App version</dt>
                <dd>
                  {window.MGB_VERSION
                    ? `${window.MGB_VERSION.label} — ${window.MGB_VERSION.note}`
                    : "Not set"}
                  <div style={{ marginTop: 6 }}>
                    <button
                      className="btn-secondary"
                      onClick={() => window.location.reload()}
                    >
                      Reload for the latest
                    </button>
                  </div>
                </dd>
              </div>
              <div>
                <dt>Supabase project</dt>
                <dd>
                  {supabase && window.SUPABASE_CONFIG
                    ? new URL(window.SUPABASE_CONFIG.url).host
                    : "Not configured"}
                </dd>
              </div>
              <div>
                <dt>Staff table read</dt>
                <dd
                  className={
                    staffReadOk === false
                      ? "negative"
                      : staffReadOk
                        ? "positive"
                        : ""
                  }
                >
                  {staffReadOk === false
                    ? `Failing — ${staffReadError}`
                    : staffReadOk
                      ? "OK"
                      : "Checking…"}
                </dd>
              </div>
              <div>
                <dt>Audit log read</dt>
                <dd
                  className={
                    auditError ? "negative" : auditRows ? "positive" : ""
                  }
                >
                  {auditError
                    ? "Failing — run staff-audit-log.sql"
                    : auditRows
                      ? "OK"
                      : "Checking…"}
                </dd>
              </div>
              {staffUser && (
                <div>
                  <dt>Signed in as</dt>
                  <dd>
                    {staffUser.name} ({staffUser.email}) · {staffUser.role}
                  </dd>
                </div>
              )}
            </dl>
          </div>

          <div className="card">
            <h3 className="card-title">Send me a test email</h3>
            <p className="card-subtitle">
              Sends a short email to your own address
              {staffUser ? ` (${staffUser.email})` : ""} through the firm's
              sender, so you can confirm email works without involving a
              client. Nothing else is sent.
            </p>
            <div className="staff-reset-row">
              <button
                className="btn-secondary"
                onClick={sendTestEmail}
                disabled={testEmail.busy || !supabase}
              >
                {testEmail.busy ? "Sending…" : "Send test email"}
              </button>
              {testEmail.text && (
                <p
                  className="card-subtitle"
                  style={{
                    margin: 0,
                    color:
                      testEmail.ok === false
                        ? "var(--bad)"
                        : testEmail.ok
                          ? "var(--good)"
                          : undefined,
                  }}
                >
                  {testEmail.text}
                </p>
              )}
            </div>
          </div>

          <div className="card">
            <h3 className="card-title">Where things live</h3>
            <p className="card-subtitle">
              A directory, not a vault — this doesn't store any real
              credentials. Edit <code>INFRA_LINKS</code> in app.jsx when an
              account changes.
            </p>
            <div className="staff-audit-list">
              {INFRA_LINKS.map((l) => (
                <a
                  className="staff-due-row"
                  href={l.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  key={l.name}
                >
                  <span className="staff-flag-label">{l.name}</span>
                  <span className="staff-flag-desc">{l.note}</span>
                </a>
              ))}
            </div>
          </div>
        </div>
      </fieldset>
    </div>
  );
}

// ----------------------------------------------------------------------------
// Team Chat — internal staff messaging, separate from client conversations
// (client_messages; both live in the unified inbox, components/inbox/). Any active
// staff member can DM any other active staff member (bookkeepers included —
// two bookkeepers working the same client need this as much as a bookkeeper
// <-> admin line does), on real Supabase tables (staff_conversations /
// staff_conversation_members / staff_messages), with file attachments,
// edit within 15 minutes of sending, delete within 24 hours (the author
// only; the message then disappears for everyone, see
// supabase/message-delete-24h.sql), and live read receipts pushed
// over Supabase Realtime.
// ----------------------------------------------------------------------------

// 15 minutes, not 5 seconds — the old window (staff-chat-v2.sql) expired
// before most people finished typing a fix, so Edit/Unsend looked broken
// even though it was working exactly as configured. Mirrored in
// supabase/staff-chat-groups.sql's RLS policy; both must be changed together.
const CHAT_EDIT_WINDOW_MS = 15 * 60 * 1000;
// Delete is allowed for 24 hours after sending. Mirrored in
// delete_staff_message / delete_client_message (supabase/message-delete-24h.sql),
// which are the real enforcement; this only decides when to show the button.
const MSG_DELETE_WINDOW_MS = 24 * 60 * 60 * 1000;
const msgCanDelete = (createdAt) =>
  !!createdAt && Date.now() - new Date(createdAt).getTime() < MSG_DELETE_WINDOW_MS;

// Security audit finding: attachments were staged and uploaded with no size
// or type check at all, so the staff-chat-attachments bucket would take an
// arbitrarily large file of any type from any signed-in staffer. Mirrored
// server-side in supabase/audit2-storage-limits.sql (the bucket's own
// file_size_limit / allowed_mime_types); both must be changed together —
// this pair is the friendly error, that one is the actual enforcement.
const MAX_ATTACHMENT_BYTES = 25 * 1024 * 1024;
const ALLOWED_ATTACHMENT_TYPES = new Set([
  "application/pdf",
  "image/png",
  "image/jpeg",
  "image/gif",
  "image/webp",
  "text/csv",
  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", // .xlsx
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document", // .docx
  "text/plain",
]);

// Team Chat state and actions, shared by the unified inbox
// (components/inbox/StaffInbox.jsx, the Team Chat page and the chat drawer)
// and the fallback page below. Mount one at a time: its Realtime channel
// names are fixed per staffer. enabled=false leaves it inert (no queries,
// no channels), for the client-only inbox on a client's Messages tab.
function useStaffTeamChat(staffUser, onActivity, enabled = true) {
  const supabase = enabled ? window.mgbSupabase : null;
  const showToast = useToast();

  const [directory, setDirectory] = useState(null); // every other active staff member
  const [conversations, setConversations] = useState(null); // my conversations, most recent first
  const [activeConversationId, setActiveConversationId] = useState(null);
  const [activeMembers, setActiveMembers] = useState(null); // [{staff_email, last_read_at}] for the open conversation
  const [messages, setMessages] = useState(null);
  const [loadError, setLoadError] = useState("");
  const [draft, setDraft] = useState("");
  const [pendingAttachment, setPendingAttachment] = useState(null); // {file, name, size}
  const [isDragging, setIsDragging] = useState(false);
  const [sending, setSending] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [editDraft, setEditDraft] = useState("");
  const [confirmDeleteId, setConfirmDeleteId] = useState(null); // inline "Delete this message?" on one of my messages
  const [, setTick] = useState(0); // forces a re-render so the edit window visibly expires
  const [threadFilter, setThreadFilter] = useState("");
  const [showGroupModal, setShowGroupModal] = useState(false);
  const [onlineEmails, setOnlineEmails] = useState(new Set()); // Realtime Presence
  const [typingName, setTypingName] = useState(null); // Realtime Broadcast, active conversation only
  const fileInputRef = useRef(null);
  const typingChannelRef = useRef(null);
  const typingTimeoutRef = useRef(null);
  const lastTypingSentRef = useRef(0);
  // Security audit finding: resolves a typing broadcast's sender email to a
  // name we can trust. Held in a ref (kept current by the effect below) so
  // the typing channel doesn't have to resubscribe every time the member
  // list or the staff directory loads.
  const displayNameForRef = useRef(() => "Someone");
  // Guards against a stale async openWith() resolving after the user has
  // already clicked to a different thread and overwriting their new
  // selection — see selectConversation/openWith below. This was the actual
  // cause of "I messaged Gillian and Jeff got it": clicking Gillian (no
  // conversation yet) kicked off an insert; if Send was hit before that
  // insert resolved, it fired against whatever activeConversationId still
  // held — Jeff's, left over from before.
  const openTokenRef = useRef(0);

  useEffect(() => {
    if (!supabase) return;
    supabase
      .from("staff")
      .select("email, name, role, active")
      .eq("active", true)
      .neq("email", staffUser.email)
      .order("name", { ascending: true })
      .then(({ data, error }) => {
        if (!error) setDirectory(data);
      });
  }, [supabase, staffUser.email]);

  const loadConversations = useCallback(() => {
    if (!supabase) return;
    supabase
      .from("staff_conversation_members")
      .select("conversation_id, last_read_at")
      .eq("staff_email", staffUser.email)
      .then(async ({ data, error }) => {
        if (error || !data || data.length === 0) {
          setConversations([]);
          return;
        }
        const convIds = data.map((r) => r.conversation_id);
        const myReadByConv = {};
        data.forEach((r) => {
          myReadByConv[r.conversation_id] = r.last_read_at;
        });

        let [
          { data: otherMembers },
          { data: recentMessages },
          { data: convRows, error: convErr },
        ] = await Promise.all([
          supabase
            .from("staff_conversation_members")
            .select("conversation_id, staff_email")
            .in("conversation_id", convIds)
            .neq("staff_email", staffUser.email),
          supabase
            .from("staff_messages")
            .select(
              "conversation_id, author_email, text, attachment_name, created_at",
            )
            .in("conversation_id", convIds)
            .is("deleted_at", null)
            .order("created_at", { ascending: false }),
          // is_group/title only exist once staff-chat-groups.sql has been run —
          // an older DB just won't have any group conversations to find here.
          supabase
            .from("staff_conversations")
            .select("id, is_group, title, retired_at")
            .in("id", convIds),
        ]);
        // retired_at arrives with staff-chat-retire-groups.sql; before that,
        // read the older columns so the list still loads.
        if (convErr) {
          ({ data: convRows } = await supabase
            .from("staff_conversations")
            .select("id, is_group, title")
            .in("id", convIds));
        }

        // A group has 2+ "other" members, so this collects an array per
        // conversation rather than the single email a 1:1 DM used to assume
        // (that assumption is what silently mislabeled groups before).
        const othersByConv = {};
        (otherMembers || []).forEach((m) => {
          (
            othersByConv[m.conversation_id] ||
            (othersByConv[m.conversation_id] = [])
          ).push(m.staff_email);
        });
        const convMetaById = {};
        (convRows || []).forEach((c) => {
          convMetaById[c.id] = c;
        });
        const otherEmails = [...new Set(Object.values(othersByConv).flat())];
        let staffByEmail = {};
        if (otherEmails.length > 0) {
          const { data: staffRows } = await supabase
            .from("staff")
            .select("email, name, role")
            .in("email", otherEmails);
          (staffRows || []).forEach((s) => {
            staffByEmail[s.email] = s;
          });
        }
        const lastByConv = {};
        (recentMessages || []).forEach((m) => {
          if (!lastByConv[m.conversation_id]) lastByConv[m.conversation_id] = m;
        });

        const rows = convIds.map((id) => {
          const meta = convMetaById[id] || {};
          const otherEmailsForConv = othersByConv[id] || [];
          const otherNames = otherEmailsForConv.map((e) =>
            staffByEmail[e] ? staffByEmail[e].name : e,
          );
          const isGroup = !!meta.is_group;
          const last = lastByConv[id];
          const myReadAt = myReadByConv[id];
          const unread =
            !!last &&
            last.author_email !== staffUser.email &&
            (!myReadAt || new Date(last.created_at) > new Date(myReadAt));
          return {
            id,
            isGroup,
            otherEmail: !isGroup ? otherEmailsForConv[0] || null : null,
            otherEmails: otherEmailsForConv,
            otherName: isGroup
              ? meta.title || otherNames.join(", ") || "Group"
              : otherNames[0] || otherEmailsForConv[0] || "Unknown",
            otherRole: isGroup
              ? `${otherEmailsForConv.length + 1} people`
              : (staffByEmail[otherEmailsForConv[0]] || {}).role || "",
            lastText: last
              ? last.text ||
                (last.attachment_name
                  ? `Attachment: ${last.attachment_name}`
                  : "")
              : "",
            lastAt: last ? last.created_at : null,
            unread,
            retired: !!meta.retired_at,
          };
        });
        rows.sort((a, b) => new Date(b.lastAt || 0) - new Date(a.lastAt || 0));
        setConversations(rows);
      });
  }, [supabase, staffUser.email]);

  useEffect(() => {
    loadConversations();
  }, [loadConversations]);

  const markRead = useCallback(
    (conversationId) => {
      if (!supabase || !conversationId) return;
      supabase
        .from("staff_conversation_members")
        .update({ last_read_at: new Date().toISOString() })
        .eq("conversation_id", conversationId)
        .eq("staff_email", staffUser.email)
        .then(() => {
          loadConversations();
          if (onActivity) onActivity();
        });
    },
    [supabase, staffUser.email, loadConversations, onActivity],
  );

  // Same stale-response guard as openTokenRef above, which was added after
  // "I messaged Gillian and Jeff got it" — it was never extended to this
  // fetch. Click a big thread, then immediately a small one: the small one
  // resolves first and renders correctly, then the big one's slower response
  // lands and overwrites the pane, so you're reading conversation A's
  // messages under conversation B's header. Every response now checks that
  // it is still the most recent request before it writes any state.
  const messagesLoadTokenRef = useRef(0);

  const loadMessages = useCallback(() => {
    if (!supabase || !activeConversationId) return;
    const token = ++messagesLoadTokenRef.current;
    const isStale = () => token !== messagesLoadTokenRef.current;
    const convId = activeConversationId;
    Promise.all([
      supabase
        .from("staff_messages")
        .select(
          "id, conversation_id, author_email, author_name, author_role, text, attachment_name, attachment_url, attachment_size, created_at, edited_at, deleted_at",
        )
        .eq("conversation_id", activeConversationId)
        .is("deleted_at", null)
        .order("created_at", { ascending: true }),
      supabase
        .from("staff_conversation_members")
        .select("staff_email, last_read_at")
        .eq("conversation_id", activeConversationId),
    ]).then(async ([msgRes, memRes]) => {
      if (isStale()) return;
      if (msgRes.error) {
        setLoadError(
          "Couldn't load messages. Has staff-chat-v2.sql been run? " +
            msgRes.error.message,
        );
        setMessages([]);
        return;
      }
      setLoadError("");
      // A deleted message (Delete, or an old Unsend) disappears completely,
      // as if it was never sent: the query above leaves it out, and this
      // catches anything that slips through.
      const visible = (msgRes.data || []).filter((m) => !m.deleted_at);
      // Security audit finding C1: attachment_url is now a private storage
      // path, not a public URL — resolve a short-lived signed URL per
      // attachment before rendering. Any that fail to sign (deleted object,
      // etc) just render without a working link.
      const withAttachments = visible.filter((m) => m.attachment_url);
      if (withAttachments.length) {
        const signed = await Promise.all(
          withAttachments.map((m) =>
            supabase.storage
              .from("staff-chat-attachments")
              .createSignedUrl(m.attachment_url, 60 * 10)
              .then(({ data }) => [m.id, data && data.signedUrl]),
          ),
        );
        // Signing is a second round trip, so re-check after awaiting it.
        if (isStale()) return;
        const signedMap = Object.fromEntries(signed);
        setMessages(
          visible.map((m) =>
            m.attachment_url
              ? { ...m, attachment_signed_url: signedMap[m.id] || null }
              : m,
          ),
        );
      } else {
        setMessages(visible);
      }
      setActiveMembers(memRes.data || []);
      markRead(convId);
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [supabase, activeConversationId]);

  useEffect(() => {
    loadMessages();
  }, [loadMessages]);

  // Live updates: new messages, edits/deletes, and the other side marking
  // the thread read, all pushed in — no polling, no manual refresh needed
  // to see a reply or watch "Sent" flip to "Seen".
  const conversationIdsRef = useRef(new Set());
  useEffect(() => {
    conversationIdsRef.current = new Set(
      (conversations || []).map((c) => c.id),
    );
  }, [conversations]);
  const activeConversationIdRef = useRef(null);
  useEffect(() => {
    activeConversationIdRef.current = activeConversationId;
  }, [activeConversationId]);

  useEffect(() => {
    if (!supabase) return;
    const channel = supabase
      // Security audit finding: private channel, so Realtime checks the
      // caller against realtime.messages RLS instead of letting anyone with
      // the publishable key subscribe to this topic.
      .channel("staff-chat-" + staffUser.email, { config: { private: true } })
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "staff_messages" },
        (payload) => {
          const convId =
            (payload.new && payload.new.conversation_id) ||
            (payload.old && payload.old.conversation_id);
          if (!convId) return;
          if (convId === activeConversationIdRef.current) loadMessages();
          loadConversations();
          if (onActivity) onActivity();
        },
      )
      .on(
        "postgres_changes",
        {
          event: "UPDATE",
          schema: "public",
          table: "staff_conversation_members",
        },
        (payload) => {
          const convId = payload.new && payload.new.conversation_id;
          if (convId && convId === activeConversationIdRef.current)
            loadMessages();
          loadConversations();
        },
      )
      .subscribe();
    return () => {
      supabase.removeChannel(channel);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [supabase, staffUser.email]);

  // Realtime Presence: one shared channel every signed-in staff member
  // joins, keyed by their own email. `sync` fires with the full roster
  // whenever anyone joins/leaves, so onlineEmails is always just "who's in
  // presenceState() right now" — no polling, no manual heartbeat.
  useEffect(() => {
    if (!supabase) return;
    const channel = supabase.channel("staff-presence", {
      // Security audit finding: private, same as the inbox channel above —
      // the roster of who's online is staff-only.
      config: { private: true, presence: { key: staffUser.email } },
    });
    channel
      .on("presence", { event: "sync" }, () => {
        setOnlineEmails(new Set(Object.keys(channel.presenceState())));
      })
      .subscribe(async (status) => {
        if (status === "SUBSCRIBED")
          await channel.track({ online_at: new Date().toISOString() });
      });
    return () => {
      supabase.removeChannel(channel);
    };
  }, [supabase, staffUser.email]);

  useEffect(() => {
    displayNameForRef.current = (email) => {
      if (!email) return "Someone";
      // Must actually be in the open conversation — a broadcast from anyone
      // else on the channel gets the generic label, not a staff name.
      const isMember = (activeMembers || []).some(
        (mm) => mm.staff_email === email,
      );
      if (!isMember) return "Someone";
      if (email === staffUser.email) return staffUser.name || "Someone";
      const row = (directory || []).find((d) => d.email === email);
      return (row && row.name) || "Someone";
    };
  }, [activeMembers, directory, staffUser.email, staffUser.name]);

  // Realtime Broadcast, scoped to whichever conversation is open — a fresh
  // channel per activeConversationId (not the per-user inbox channel above,
  // which isn't shared between the two people in a DM). Typing pulses reset
  // a 3s timeout rather than an explicit "stopped typing" event, so it also
  // self-clears if the other tab closes mid-keystroke.
  useEffect(() => {
    setTypingName(null);
    typingChannelRef.current = null;
    if (!supabase || !activeConversationId) return;
    const channel = supabase.channel("conv-typing-" + activeConversationId, {
      config: { private: true },
    });
    channel
      .on("broadcast", { event: "typing" }, ({ payload }) => {
        if (!payload || payload.email === staffUser.email) return;
        // Security audit finding: payload.name is attacker-controlled — it's
        // whatever the sending tab put in the broadcast, not anything the
        // server vouches for, so rendering it let someone on the channel
        // impersonate any staff member in the "X is typing…" line. Resolve
        // the display name ourselves from the sender's email: they must be a
        // member of THIS conversation, and the name comes from the `staff`
        // directory row, never from the wire.
        setTypingName(displayNameForRef.current(payload.email));
        clearTimeout(typingTimeoutRef.current);
        typingTimeoutRef.current = setTimeout(() => setTypingName(null), 3000);
      })
      .subscribe((status) => {
        if (status === "SUBSCRIBED") typingChannelRef.current = channel;
      });
    return () => {
      clearTimeout(typingTimeoutRef.current);
      supabase.removeChannel(channel);
      typingChannelRef.current = null;
    };
  }, [supabase, activeConversationId, staffUser.email]);

  const notifyTyping = () => {
    const now = Date.now();
    if (!typingChannelRef.current || now - lastTypingSentRef.current < 1500)
      return;
    lastTypingSentRef.current = now;
    typingChannelRef.current.send({
      type: "broadcast",
      event: "typing",
      payload: { email: staffUser.email, name: staffUser.name },
    });
  };

  // Live-expire the edit window on-screen without needing another
  // action to trigger a re-render.
  useEffect(() => {
    const hasRecent = (messages || []).some(
      (m) =>
        m.author_email === staffUser.email &&
        Date.now() - new Date(m.created_at).getTime() < CHAT_EDIT_WINDOW_MS,
    );
    if (!hasRecent) return;
    const id = setInterval(() => setTick((t) => t + 1), 1000);
    return () => clearInterval(id);
  }, [messages, staffUser.email]);

  // token: this call's own stamp from openTokenRef, taken at click time by
  // selectConversation below. If the user has since clicked a different
  // thread (bumping the ref), this result is stale and must NOT overwrite
  // activeConversationId — that's what let a message meant for a brand-new
  // conversation land in whatever conversation was active before it.
  const openWith = useCallback(
    (otherEmail, token) => {
      if (!supabase || !otherEmail) return;
      const dmKey = [staffUser.email, otherEmail].sort().join("|");
      supabase
        .from("staff_conversations")
        .select("id")
        .eq("dm_key", dmKey)
        .maybeSingle()
        .then(async ({ data: existing }) => {
          if (existing) {
            if (openTokenRef.current === token)
              setActiveConversationId(existing.id);
            return;
          }
          const { data: created, error } = await supabase
            .from("staff_conversations")
            .insert({ dm_key: dmKey })
            .select("id")
            .single();
          if (error || !created) {
            showToast("Couldn't start the conversation.");
            return;
          }
          await supabase.from("staff_conversation_members").insert([
            {
              conversation_id: created.id,
              staff_email: staffUser.email,
              last_read_at: new Date().toISOString(),
            },
            { conversation_id: created.id, staff_email: otherEmail },
          ]);
          if (openTokenRef.current === token)
            setActiveConversationId(created.id);
          loadConversations();
        });
    },
    [supabase, staffUser.email, loadConversations, showToast],
  );

  // Every thread click (existing conversation or a fresh 1:1) goes through
  // here so switching always clears the old thread's messages immediately —
  // otherwise the previous conversation's messages (and its
  // activeConversationId) stay on screen/active while the new one loads,
  // which is exactly the gap the openWith race above could land a message in.
  const selectConversation = useCallback(
    (c) => {
      openTokenRef.current += 1;
      const token = openTokenRef.current;
      setActiveConversationId(null);
      setMessages(null);
      setActiveMembers(null);
      if (c.id) {
        if (openTokenRef.current === token) setActiveConversationId(c.id);
        return;
      }
      openWith(c.otherEmail, token);
    },
    [openWith],
  );

  const createGroup = useCallback(
    async (emails, title) => {
      if (!supabase || emails.length < 2) return;
      const { data: created, error } = await supabase
        .from("staff_conversations")
        .insert({ is_group: true, title: title.trim() || null })
        .select("id")
        .single();
      if (error || !created) {
        showToast(
          error && /is_group|column/i.test(error.message || "")
            ? "Couldn't create the group — has staff-chat-groups.sql been run?"
            : "Couldn't create the group.",
        );
        return;
      }
      await supabase.from("staff_conversation_members").insert([
        {
          conversation_id: created.id,
          staff_email: staffUser.email,
          last_read_at: new Date().toISOString(),
        },
        ...emails.map((email) => ({
          conversation_id: created.id,
          staff_email: email,
        })),
      ]);
      setShowGroupModal(false);
      openTokenRef.current += 1;
      setActiveConversationId(created.id);
      setMessages(null);
      setActiveMembers(null);
      loadConversations();
    },
    [supabase, staffUser.email, loadConversations, showToast],
  );

  const stageFile = (file) => {
    if (!file) return;
    if (file.size > MAX_ATTACHMENT_BYTES) {
      showToast(
        `${file.name} is ${formatBytes(file.size)} — attachments are capped at 25 MB.`,
      );
      return;
    }
    // Browsers leave file.type empty for extensions they don't recognize, so
    // an unknown type is rejected rather than waved through.
    if (!ALLOWED_ATTACHMENT_TYPES.has(file.type)) {
      showToast(
        `Can't attach ${file.name} — PDF, image, CSV, Excel, Word and text files only.`,
      );
      return;
    }
    setPendingAttachment({
      file,
      name: file.name,
      size: formatBytes(file.size),
    });
  };

  async function send() {
    if (
      (!draft.trim() && !pendingAttachment) ||
      !activeConversationId ||
      !supabase
    )
      return;
    setSending(true);
    // Everything below used to run with no try/catch: any REJECTED promise
    // (a thrown network/CORS/timeout error, as opposed to a resolved
    // {error} response) skipped straight past every setSending(false) call
    // below, leaving Send permanently disabled and the attachment stuck
    // staged with zero feedback — "it's sending but not going anywhere."
    // upload()/insert() normally resolve with {error} rather than throw, but
    // "normally" isn't a guarantee, and the one path that must never happen
    // is the button getting stuck. finally covers every exit.
    try {
      let attachment_name = null;
      let attachment_url = null;
      let attachment_size = null;
      if (pendingAttachment) {
        // Supabase Storage keys reject characters a real filename has all
        // the time (#, %, &, ?, +, non-ASCII…). Unsanitized, a name like
        // "Q3 Report #2.pdf" made the upload fail outright — and since
        // send() used to bail before ever inserting the message row, that
        // attempt left nothing behind at all: no message, no file, nothing
        // to retry from but re-attaching. attachment_name (below) keeps the
        // real name for display; only the storage key itself needs to be safe.
        const safeName = pendingAttachment.file.name.replace(
          /[^a-zA-Z0-9._-]/g,
          "_",
        );
        const path = `${activeConversationId}/${Date.now()}-${safeName}`;
        const { error: upErr } = await supabase.storage
          .from("staff-chat-attachments")
          .upload(path, pendingAttachment.file);
        if (upErr) {
          showToast(`Couldn't upload attachment: ${upErr.message}`);
          return;
        }
        // Security audit finding C1: the bucket is private now, so we store
        // the storage *path* (not a public URL) and mint a short-lived
        // signed URL at render time instead — see attachmentSignedUrl below.
        attachment_name = pendingAttachment.file.name;
        attachment_url = path;
        attachment_size = pendingAttachment.size;
      }
      // Security audit finding M1: author_name/author_role are no longer
      // sent from the client — a `before insert` trigger on staff_messages
      // (see staff-chat-v2.sql) overwrites both from the `staff` table
      // server-side, so a spoofed display name/role can't be stored even if
      // a caller sends one.
      const { error } = await supabase.from("staff_messages").insert({
        conversation_id: activeConversationId,
        author_email: staffUser.email,
        text: draft.trim() || null,
        attachment_name,
        attachment_url,
        attachment_size,
      });
      if (error) {
        showToast(`Couldn't send: ${error.message}`);
        return;
      }
      setDraft("");
      setPendingAttachment(null);
      loadMessages();
    } catch (err) {
      showToast(
        `Couldn't send: ${err && err.message ? err.message : "unexpected error"}`,
      );
    } finally {
      setSending(false);
    }
  }

  function startEdit(m) {
    setEditingId(m.id);
    setEditDraft(m.text || "");
  }

  async function saveEdit(id) {
    const text = editDraft.trim();
    if (!text || !supabase) return;
    const { error } = await supabase
      .from("staff_messages")
      .update({ text, edited_at: new Date().toISOString() })
      .eq("id", id);
    if (error)
      showToast("Couldn't save — the 15 minute edit window has passed.");
    setEditingId(null);
    loadMessages();
  }

  // Author-only soft delete, within 24 hours of sending. Goes through an
  // RPC rather than the 15 minute edit policy: delete_staff_message stamps
  // deleted_at / deleted_by and clears the text, and nothing else. The
  // message then drops out of the thread, the list preview and unread for
  // everyone; other members see it go through the Realtime subscription
  // above, same as an edit.
  async function deleteMessage(id) {
    setConfirmDeleteId(null);
    if (!supabase) return;
    const { error } = await supabase.rpc("delete_staff_message", { p_id: id });
    if (error) showToast(`Couldn't delete: ${error.message}`);
    else setMessages((prev) => (prev || []).filter((m) => m.id !== id));
    loadMessages();
    loadConversations();
    if (onActivity) onActivity();
  }

  // Recent conversations first, then anyone in the directory not yet
  // messaged (1:1 only — a group thread is always started explicitly via
  // "New Group", never implied by a directory row), so opening a new
  // conversation is just picking a name rather than a separate flow.
  const chatEntries = useMemo(() => {
    if (!directory) return [];
    const convEmails = new Set(
      (conversations || []).filter((c) => !c.isGroup).map((c) => c.otherEmail),
    );
    const withoutConv = directory
      .filter((d) => !convEmails.has(d.email))
      .map((d) => ({
        id: null,
        otherEmail: d.email,
        otherName: d.name,
        otherRole: d.role,
        lastText: "",
        lastAt: null,
        unread: false,
        isGroup: false,
      }));
    withoutConv.sort((a, b) => a.otherName.localeCompare(b.otherName));
    // Unread first (most recent unread first), then everything else by
    // recency — an unread thread three days old shouldn't hide below five
    // read ones from this morning.
    const sortedConversations = [...(conversations || [])].sort((a, b) => {
      if (a.unread !== b.unread) return a.unread ? -1 : 1;
      return new Date(b.lastAt || 0) - new Date(a.lastAt || 0);
    });
    const combined = [...sortedConversations, ...withoutConv];
    const q = threadFilter.trim().toLowerCase();
    return q
      ? combined.filter((c) => c.otherName.toLowerCase().includes(q))
      : combined;
  }, [directory, conversations, threadFilter]);

  const activeEntry = chatEntries.find((c) =>
    c.id ? c.id === activeConversationId : false,
  );
  const otherActiveMembers = (activeMembers || []).filter(
    (mm) => mm.staff_email !== staffUser.email,
  );
  const otherMember =
    otherActiveMembers.length === 1 ? otherActiveMembers[0] : null;
  const otherHasSeen = (m) =>
    !!(
      otherMember &&
      otherMember.last_read_at &&
      new Date(otherMember.last_read_at) >= new Date(m.created_at)
    );
  const seenCount = (m) =>
    otherActiveMembers.filter(
      (mm) =>
        mm.last_read_at && new Date(mm.last_read_at) >= new Date(m.created_at),
    ).length;
  let lastMineMessage = null;
  (messages || []).forEach((m) => {
    if (m.author_email === staffUser.email && !m.deleted_at)
      lastMineMessage = m;
  });

  // Retire (hide, read-only, reversible) or restore a group; any member can.
  // Admins can then delete a retired group for good.
  const setGroupRetired = useCallback(
    async (id, retire) => {
      if (!supabase || !id) return false;
      const { error } = await supabase.rpc("set_staff_group_retired", {
        p_id: id,
        p_retire: retire,
      });
      if (error) {
        showToast(
          retire ? "Couldn't retire the group." : "Couldn't restore the group.",
        );
        return false;
      }
      showToast(retire ? "Group retired." : "Group restored.");
      loadConversations();
      return true;
    },
    [supabase, loadConversations],
  );
  const deleteGroup = useCallback(
    async (id) => {
      if (!supabase || !id) return false;
      const { error } = await supabase.rpc("delete_staff_group", { p_id: id });
      if (error) {
        showToast("Couldn't delete the group.");
        return false;
      }
      showToast("Group deleted.");
      if (activeConversationId === id) {
        setActiveConversationId(null);
        setMessages(null);
        setActiveMembers(null);
      }
      loadConversations();
      return true;
    },
    [supabase, loadConversations, activeConversationId],
  );

  return {
    setGroupRetired, deleteGroup,
    staffUser, directory, conversations, activeConversationId, activeMembers,
    messages, loadError, draft, setDraft, pendingAttachment, setPendingAttachment,
    isDragging, setIsDragging, sending, editingId, setEditingId, editDraft,
    setEditDraft, threadFilter, setThreadFilter, showGroupModal,
    setShowGroupModal, onlineEmails, typingName, fileInputRef, notifyTyping,
    selectConversation, createGroup, stageFile, send, startEdit, saveEdit,
    deleteMessage, confirmDeleteId, setConfirmDeleteId, chatEntries, activeEntry, otherActiveMembers, otherHasSeen,
    seenCount, lastMineMessage, loadConversations,
  };
}

// The open Team Chat conversation: messages, attachments, edit within the
// window, delete (own messages, within 24 hours; the message disappears),
// read receipts and typing. `chat` is useStaffTeamChat's result;
// hideTitle is for the inbox, which draws its own header.
function StaffTeamThread({ chat, hideTitle }) {
  const {
    staffUser, activeConversationId, messages, loadError, draft, setDraft,
    pendingAttachment, setPendingAttachment, isDragging, setIsDragging, sending,
    editingId, setEditingId, editDraft, setEditDraft, onlineEmails, typingName,
    fileInputRef, notifyTyping, stageFile, send, startEdit, saveEdit,
    deleteMessage, confirmDeleteId, setConfirmDeleteId, activeEntry, otherActiveMembers, otherHasSeen, seenCount, lastMineMessage,
  } = chat;
  if (!activeConversationId) return null;
  return (
    <div
      className={"card message-card" + (isDragging ? " dragging" : "")}
      onDragOver={(e) => {
        e.preventDefault();
        setIsDragging(true);
      }}
      onDragLeave={() => setIsDragging(false)}
      onDrop={(e) => {
        e.preventDefault();
        setIsDragging(false);
        stageFile(e.dataTransfer.files && e.dataTransfer.files[0]);
      }}
    >
{!hideTitle && (
        <h3 className="card-title">
          {activeEntry &&
            (activeEntry.isGroup
              ? activeEntry.otherEmails.some((e) => onlineEmails.has(e))
              : onlineEmails.has(activeEntry.otherEmail)) && (
              <span
                className="online-dot"
                aria-label="Online"
                title="Online now"
              />
            )}
          {activeEntry
            ? `Conversation with ${activeEntry.otherName}`
            : "Conversation"}
        </h3>
      )}
      {loadError && <p className="card-subtitle negative">{loadError}</p>}
      {messages === null && !loadError && (
        <p className="card-subtitle">Loading…</p>
      )}
      {messages && messages.length === 0 && !loadError && (
        <p className="card-subtitle">No messages yet — say hello.</p>
      )}
      {messages && messages.length > 0 && (
        <div className="message-thread">
          {messages.map((m) => {
            const mine = m.author_email === staffUser.email;
            const withinWindow =
              mine &&
              Date.now() - new Date(m.created_at).getTime() <
                CHAT_EDIT_WINDOW_MS;
            const canDelete = mine && msgCanDelete(m.created_at);
            return (
              <div
                className={
                  "message-bubble-row " + (mine ? "client" : "bookkeeper")
                }
                key={m.id}
              >
                <div className="message-bubble">
                  <div className="message-author">
                    {m.author_name} · {m.author_role}
                  </div>
                  {editingId === m.id ? (
                    <div className="message-edit-row">
                      <input
                        type="text"
                        value={editDraft}
                        onChange={(e) => setEditDraft(e.target.value)}
                        onKeyDown={(e) => {
                          if (e.key === "Enter") saveEdit(m.id);
                          if (e.key === "Escape") setEditingId(null);
                        }}
                        autoFocus
                      />
                      <button
                        className="btn-secondary"
                        onClick={() => saveEdit(m.id)}
                      >
                        Save
                      </button>
                    </div>
                  ) : (
                    <React.Fragment>
                      {m.text && (
                        <div className="message-text">{m.text}</div>
                      )}
                      {m.attachment_name &&
                        safeHttpUrl(m.attachment_signed_url) && (
                          <a
                            className="message-attachment"
                            href={safeHttpUrl(m.attachment_signed_url)}
                            target="_blank"
                            rel="noreferrer"
                          >
                            <PaperclipIcon /> {m.attachment_name}{" "}
                            {m.attachment_size && (
                              <span className="message-attachment-size">
                                ({m.attachment_size})
                              </span>
                            )}
                          </a>
                        )}
                      {m.attachment_name &&
                        !safeHttpUrl(m.attachment_signed_url) && (
                          <span className="message-attachment">
                            <PaperclipIcon /> {m.attachment_name}{" "}
                            {m.attachment_size && (
                              <span className="message-attachment-size">
                                ({m.attachment_size})
                              </span>
                            )}
                          </span>
                        )}
                    </React.Fragment>
                  )}
                  <div className="message-date">
                    {fmtDateTime(m.created_at)}
                    {m.edited_at && (
                      <span className="message-edited-tag"> · edited</span>
                    )}
                  </div>
                  {(withinWindow || canDelete) && editingId !== m.id && (
                    <div className="message-own-actions">
                      {confirmDeleteId === m.id ? (
                        <React.Fragment>
                          <span className="message-confirm-label">
                            Delete this message?
                          </span>
                          <button
                            type="button"
                            onClick={() => deleteMessage(m.id)}
                          >
                            Delete
                          </button>
                          <button
                            type="button"
                            onClick={() => setConfirmDeleteId(null)}
                          >
                            Cancel
                          </button>
                        </React.Fragment>
                      ) : (
                        <React.Fragment>
                          {withinWindow && (
                            <button type="button" onClick={() => startEdit(m)}>
                              Edit
                            </button>
                          )}
                          {canDelete && (
                            <button
                              type="button"
                              onClick={() => setConfirmDeleteId(m.id)}
                            >
                              Delete
                            </button>
                          )}
                        </React.Fragment>
                      )}
                    </div>
                  )}
                  {mine && m === lastMineMessage && (
                    <div className="message-seen-status">
                      {activeEntry && activeEntry.isGroup
                        ? seenCount(m) > 0
                          ? `Seen by ${seenCount(m)}/${otherActiveMembers.length}`
                          : "Sent"
                        : otherHasSeen(m)
                          ? "Seen"
                          : "Sent"}
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {pendingAttachment && (
        <div className="attachment-chip">
          <span>
            <PaperclipIcon /> {pendingAttachment.name}
          </span>
          <span className="attachment-chip-meta">
            {pendingAttachment.size}
          </span>
          <button
            className="attachment-remove"
            onClick={() => setPendingAttachment(null)}
            aria-label="Remove attachment"
          >
            ×
          </button>
        </div>
      )}

      {/* Reserves its line whether or not anyone's typing, so the
          compose bar doesn't hop up and down every time it appears. */}
      <div className="typing-indicator">
        {typingName ? `${typingName} is typing…` : " "}
      </div>

      {activeEntry && activeEntry.retired ? (
        <div className="team-retired-note">
          This group is retired, so it's read-only. Restore it to keep talking.
        </div>
      ) : (
      <div className="message-compose">
        <button
          type="button"
          className="attach-btn"
          onClick={() => fileInputRef.current.click()}
          aria-label="Attach file"
        >
          <PaperclipIcon />
        </button>
        <input
          ref={fileInputRef}
          type="file"
          style={{ display: "none" }}
          onChange={(e) => {
            stageFile(e.target.files && e.target.files[0]);
            e.target.value = "";
          }}
        />
        <input
          type="text"
          placeholder="Write a message…"
          value={draft}
          onChange={(e) => {
            setDraft(e.target.value);
            notifyTyping();
          }}
          onKeyDown={(e) => {
            if (e.key === "Enter") send();
          }}
        />
        <button
          className="btn-primary"
          onClick={send}
          disabled={sending || (!draft.trim() && !pendingAttachment)}
        >
          Send
        </button>
      </div>
      )}
    </div>
  );
}

// Team Chat page. The unified inbox replaces it when StaffInbox.jsx is
// loaded; otherwise the original picker-and-thread layout below.
function StaffMessagesPage(props) {
  if (typeof StaffInbox === "function") return <StaffInbox {...props} />;
  return <StaffMessagesLegacy staffUser={props.staffUser} onActivity={props.onActivity} />;
}

function StaffMessagesLegacy({ staffUser, onActivity }) {
  const chat = useStaffTeamChat(staffUser, onActivity);
  const {
    directory, chatEntries, activeConversationId, onlineEmails, threadFilter,
    setThreadFilter, showGroupModal, setShowGroupModal, selectConversation,
    createGroup,
  } = chat;
  return (
    <div>
      <MockBanner text="Internal only — separate from client conversations. Nothing here is visible to any client." />

      <div className="thread-picker">
        <div className="thread-picker-toolbar">
          <span className="thread-picker-label">Conversation with</span>
          <input
            type="text"
            className="thread-filter-input"
            placeholder="Find a person or group…"
            value={threadFilter}
            onChange={(e) => setThreadFilter(e.target.value)}
          />
          <button
            type="button"
            className="btn-secondary"
            onClick={() => setShowGroupModal(true)}
          >
            + New Group
          </button>
        </div>
        {directory === null ? (
          <p className="card-subtitle">Loading…</p>
        ) : chatEntries.length === 0 ? (
          <p className="card-subtitle">
            {threadFilter ? "No matches." : "No other active staff yet."}
          </p>
        ) : (
          <div className="thread-picker-tabs">
            {chatEntries.map((c) => (
              <button
                key={c.id || c.otherEmail}
                className={
                  "thread-tab" +
                  ((c.id ? c.id === activeConversationId : false)
                    ? " active"
                    : "") +
                  (c.isGroup ? " thread-tab-group" : "") +
                  (c.unread ? " thread-tab-unread" : "")
                }
                onClick={() => selectConversation(c)}
              >
                <span className="thread-tab-name">
                  {/* Presence, not a stored column — reflects who's on the channel
                      right now, not "was active as of last page load". */}
                  {(c.isGroup
                    ? c.otherEmails.some((e) => onlineEmails.has(e))
                    : onlineEmails.has(c.otherEmail)) && (
                    <span
                      className="online-dot"
                      aria-label="Online"
                      title="Online now"
                    />
                  )}
                  {c.otherName}
                </span>
                <span className="thread-tab-role">{c.otherRole}</span>
                {c.lastText && (
                  <span className="thread-tab-preview">{c.lastText}</span>
                )}
                {c.unread && (
                  <span className="thread-tab-dot" aria-label="Unread" />
                )}
              </button>
            ))}
          </div>
        )}
      </div>

      <StaffTeamThread chat={chat} />

      {showGroupModal && (
        <GroupComposeModal
          directory={directory || []}
          onCreate={createGroup}
          onClose={() => setShowGroupModal(false)}
        />
      )}
    </div>
  );
}

function GroupComposeModal({ directory, onCreate, onClose }) {
  const [selected, setSelected] = useState(new Set());
  const [title, setTitle] = useState("");
  const [creating, setCreating] = useState(false);

  const toggle = (email) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(email)) next.delete(email);
      else next.add(email);
      return next;
    });
  };

  const handleCreate = async () => {
    setCreating(true);
    await onCreate([...selected], title);
    setCreating(false);
  };

  return (
    <ModalShell onClose={onClose} labelledBy="new-group-title">
      <div className="modal-header">
        <h3 id="new-group-title">New group</h3>
        <button className="modal-close" onClick={onClose}>
          ✕
        </button>
      </div>
      <div className="modal-body">
        <label
          style={{
            display: "block",
            fontSize: 12.5,
            fontWeight: 600,
            color: "var(--text-muted)",
            marginBottom: 6,
          }}
          htmlFor="new-group-name"
        >
          Group name (optional)
        </label>
        <input
          id="new-group-name"
          type="text"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="e.g. Grace Community team"
          style={{ marginBottom: 16 }}
        />
        <p className="card-subtitle" style={{ marginTop: 0 }}>
          Pick at least 2 people. Without a name, the group is labeled by who's
          in it.
        </p>
        <div className="group-member-list">
          {directory.map((d) => (
            <label className="group-member-row" key={d.email}>
              <input
                type="checkbox"
                checked={selected.has(d.email)}
                onChange={() => toggle(d.email)}
              />
              <span className="group-member-name">{d.name}</span>
              <span className="group-member-role">{d.role}</span>
            </label>
          ))}
        </div>
        <button
          className="btn-primary"
          style={{ marginTop: 16 }}
          disabled={selected.size < 2 || creating}
          onClick={handleCreate}
        >
          {creating
            ? "Creating…"
            : `Create group${selected.size > 0 ? ` (${selected.size + 1} people)` : ""}`}
        </button>
      </div>
    </ModalShell>
  );
}

// §135: ranks pages by view count so the team can see what's actually
